-- =============================================================================
-- 496 — LE CAHIER D'EXERCICES DE 3E (partie 10)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 496 --niveau 3e --fichiers anglais.n2,anglais.n3,anglais.n4,arts-plastiques.jumelles --suffixe 10 > supabase/contenu/496_exercices_3e_10.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.n2              30 exercices · 10 chapitres
--   anglais.n3              30 exercices · 10 chapitres
--   anglais.n4              27 exercices · 9 chapitres
--   arts-plastiques.jumelles   9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La fiche de présentation de Leo","competence":"comprendre-langue","situation":"Leo se présente sur la fiche d’un nouveau club de loisirs. Lis-la attentivement pour savoir ce qu’il sait faire.","documents":[{"id":"fiche","type":"texte","genre":"lettre","titre":"Meet Leo","blocs":["My name is Leo and I’m thirteen. I can swim very fast and I can play the guitar, but I can’t cook. My little sister can speak three languages!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit ce que Leo **ne sait pas** faire.","aide":"Cherche la forme négative de *can*.","type":"zone","document":"fiche","multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"*Can* est invariable : pas de -s.","type":"trous","segments":["Leo’s sister ",0," speak three languages."],"banque":["cans","is can","can","can to"]},{"enonce":"Remets en ordre la question « Sais-tu jouer aux échecs ? ». La phrase commence par Can.","aide":"Avec *can*, pas besoin de *do* : *can* passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"Can"},{"id":"b","texte":"you"},{"id":"c","texte":"chess"},{"id":"d","texte":"play"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Leo **can’t cook** : il ne sait pas cuisiner. *Can’t* est la négation de *can*."},{"cle":{"type":"trous","trous":[["can"]]},"affichage":"can","explication":"**can** : on écrit *she can speak*, sans -s et sans *to*."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Can you play chess?** *Can* se place avant le sujet pour poser la question."}]$ex$::jsonb),
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les souvenirs de Grand-mère Ruth","competence":"manier-langue","situation":"Ruth raconte à sa petite-fille ce qu’elle savait faire autrefois, et ce qu’elle a réussi hier. Observe quel verbe elle choisit à chaque fois.","documents":[{"id":"journal","type":"texte","genre":"lettre","titre":"Ruth’s diary","blocs":["When I was a girl, I could run for miles. Yesterday the bridge was closed, but I managed to cross the river on the old boat. Next year, I will be able to buy a new bike."],"source":"Journal écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui exprime une **capacité passée générale** (ce que Ruth savait faire quand elle était petite).","aide":"Cherche le modal à la forme du passé.","type":"zone","document":"journal","multiple":false},{"enonce":"Touche maintenant le verbe qui exprime une **réussite ponctuelle** (une seule fois, hier).","aide":"Il remplace *was able to* : « elle est parvenue à… ».","type":"zone","document":"journal","multiple":false},{"enonce":"Range chaque phrase selon ce qu’elle exprime.","aide":"Cherche le marqueur de temps : *when I was five*, *yesterday*, *next year*.","type":"categories","categories":[{"id":"c0","texte":"Capacité passée générale (could)"},{"id":"c1","texte":"Réussite ponctuelle (was able to, managed to)"},{"id":"c2","texte":"Capacité future (will be able to)"}],"items":[{"id":"i0","texte":"We managed to catch the last bus."},{"id":"i1","texte":"Next year I will be able to drive."},{"id":"i2","texte":"He will be able to join us in May."},{"id":"i3","texte":"Yesterday I was able to fix my bike."},{"id":"i4","texte":"She could read at four."},{"id":"i5","texte":"I could swim when I was five."}]},{"enonce":"Complète.","aide":"Le train a été attrapé une seule fois : c’est une réussite ponctuelle.","type":"trous","segments":["The bus was late, but luckily we ",0," catch the train."],"banque":["managed to","can","could","will can"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**could** exprime une capacité passée générale : « je savais courir »."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**managed** (to) dit une réussite précise, un jour donné. On n’emploie pas *could* pour cela."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c2","i3":"c1","i4":"c0","i5":"c0"}},"explication":"**Could** pour une capacité d’autrefois, **was able to / managed to** pour une fois précise, **will be able to** pour le futur."},{"cle":{"type":"trous","trous":[["managed to"]]},"affichage":"managed to","explication":"**managed to** : une réussite ponctuelle au passé ne se dit pas avec *could* ; *will can* n’existe pas."}]$ex$::jsonb),
  ('91e30bde-808a-5d7a-a1c9-4fa7af35a772'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pas encore prête pour l’équipe de sauvetage","competence":"argumenter","situation":"Ava écrit à son ami Ben. Elle voudrait entrer dans l’équipe de sauvetage du lac, dont le règlement est affiché au club.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Ava’s email","blocs":["Hi Ben! Great news: last Saturday I was able to swim 100 metres without stopping! When I was seven, I could swim only one length. Next summer I will be able to join the lifeguard team, but at the moment I can’t dive. My coach says I might be able to compete in March."],"source":"Courriel écrit pour l’exercice"},{"id":"test","type":"tableau","titre":"Lifeguard team: swimming test","colonnes":["Test","Distance"],"lignes":[["Swim without stopping","200 m"],["Dive from the side","2 m"],["Float on your back","5 min"]],"enteteLignes":true,"source":"Règlement écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit ce qu’Ava **ne sait pas faire** en ce moment.","aide":"Cherche ce qui suit *can’t*.","type":"zone","document":"mail","multiple":false},{"enonce":"Ava a nagé 100 m sans s’arrêter. Combien de mètres lui manque-t-il pour réussir le premier test du règlement ?","aide":"Lis la distance de son courriel, puis celle du tableau.","type":"nombre","unite":"m"},{"enonce":"Dans le courriel, pourquoi Ava écrit-elle « I was able to swim 100 metres » et pas « I could swim 100 metres » ?","aide":"Compare avec « When I was seven, I could swim ».","type":"choix","options":[{"id":"a","texte":"Parce que Ava parle de son avenir"},{"id":"b","texte":"Parce que c’est une réussite précise, un samedi donné"},{"id":"c","texte":"Parce que could ne s’emploie jamais au passé"},{"id":"d","texte":"Parce que was able to est plus poli que could"}],"multiple":false},{"enonce":"Quelle phrase est correcte pour dire qu’Ava pourra participer en mars ?","aide":"Deux modaux ne se suivent pas.","type":"choix","options":[{"id":"a","texte":"She will to be able compete in March."},{"id":"b","texte":"She will can compete in March."},{"id":"c","texte":"She can will compete in March."},{"id":"d","texte":"She will be able to compete in March."}],"multiple":false},{"enonce":"Associe chaque erreur de francophone à sa correction.","aide":"Pas de -s, pas de *to*, pas de *do* avec *can*.","type":"association","gauche":[{"id":"g0","texte":"She cans swim"},{"id":"g1","texte":"I can to dive"},{"id":"g2","texte":"Do you can swim?"},{"id":"g3","texte":"I will can come"}],"droite":[{"id":"d0","texte":"I can dive"},{"id":"d1","texte":"She can swim"},{"id":"d2","texte":"Can you swim?"},{"id":"d3","texte":"I will be able to come"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m42"]},"explication":"Ava **can’t dive** : elle ne sait pas plonger pour l’instant."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 m","explication":"Le test demande 200 m et Ava a fait 100 m : il lui manque **100 m**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Réussite ponctuelle → was able to** ; *could* sert à une capacité passée générale."},{"cle":{"type":"choix","ids":["d"]},"explication":"**will be able to** : *can* n’a pas de futur, on utilise sa forme de remplacement *be able to*."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**Can** est invariable, sans *to*, pose la question lui-même, et se remplace par *be able to* au futur."}]$ex$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le règlement de la médiathèque","competence":"comprendre-langue","situation":"Camille vient s’inscrire à la médiathèque de son quartier. Elle lit le panneau du règlement avant d’entrer.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","entete":"Library rules","sousTitre":"Open from 9 a.m.","emoji":"📚","lignes":[{"texte":"Students may borrow five books.","id":"z1"},{"texte":"You may not eat in the library.","id":"z2"},{"texte":"You can use the computers for one hour.","id":"z3"}],"pied":"Thank you!","teinte":"bleu","source":"Règlement écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui **refuse** une permission.","aide":"Cherche la forme négative du modal formel.","type":"zone","document":"panneau","multiple":false},{"enonce":"Que signifie « Students may borrow five books » ?","aide":"Dans un règlement, *may* donne une autorisation.","type":"choix","options":[{"id":"a","texte":"Les élèves ont le droit d’emprunter cinq livres"},{"id":"b","texte":"Les élèves ne peuvent pas emprunter cinq livres"},{"id":"c","texte":"Les élèves emprunteront peut-être cinq livres"},{"id":"d","texte":"Les élèves doivent emprunter cinq livres"}],"multiple":false},{"enonce":"Tu frappes à la porte du directeur. Complète poliment.","aide":"C’est la formule la plus formelle, avec un adulte.","type":"trous","segments":[0," I come in?"],"banque":["May","Should","Do","Must"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**You may not eat** : *may not* refuse une permission dans un règlement écrit."},{"cle":{"type":"choix","ids":["a"]},"explication":"**may** accorde la permission : « ont le droit d’emprunter »."},{"cle":{"type":"trous","trous":[["may"]]},"affichage":"May","explication":"**May I come in?** : *may* est le modal le plus formel pour demander la permission."}]$ex$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le message de Noah à sa mère","competence":"manier-langue","situation":"Noah demande à sa mère s’il peut aller à une fête. Elle répond avec des formules de permission de plus en plus fermes.","documents":[{"id":"fete","type":"dialogue","modele":"sms","titre":"Messages de Noah et de sa mère","participants":[{"nom":"Noah","emoji":"👦","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Noah","texte":"Mum, can I go to Leo’s party on Friday?"},{"qui":"Mum","texte":"You can go, but you mustn’t come home after ten."},{"qui":"Noah","texte":"Could I stay until eleven?"},{"qui":"Mum","texte":"I’m afraid not. Last year I wasn’t allowed to stay out late either!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui exprime une **interdiction stricte**.","aide":"Il est plus fort que *can’t*.","type":"zone","document":"fete","multiple":false},{"enonce":"Classe chaque demande selon son registre.","aide":"*Can* est familier, *could* poli, *may* formel.","type":"categories","categories":[{"id":"c0","texte":"Familier (à un ami)"},{"id":"c1","texte":"Poli"},{"id":"c2","texte":"Formel (à un adulte)"}],"items":[{"id":"i0","texte":"Can I sit here?"},{"id":"i1","texte":"Could I borrow your pen?"},{"id":"i2","texte":"May I ask a question, madam?"},{"id":"i3","texte":"Could I open the window?"},{"id":"i4","texte":"May I leave the room, sir?"},{"id":"i5","texte":"Can I use your phone?"}]},{"enonce":"Que veut dire la mère par « I’m afraid not » ?","aide":"C’est une façon polie de refuser.","type":"choix","options":[{"id":"a","texte":"Peut-être demain"},{"id":"b","texte":"J’ai peur de ce que tu dis"},{"id":"c","texte":"Je regrette, mais non"},{"id":"d","texte":"Oui, bien sûr"}],"multiple":false},{"enonce":"Complète.","aide":"Il faut une forme qui se conjugue au futur.","type":"trous","segments":["In two years, Noah ",0," go to concerts alone."],"banque":["will can","may to","will be allowed to","is allow to"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**mustn’t** exprime une interdiction forte : « tu ne dois pas »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c1","i4":"c2","i5":"c0"}},"explication":"**Can** entre proches, **could** pour demander poliment, **may** dans un cadre officiel."},{"cle":{"type":"choix","ids":["c"]},"explication":"**I’m afraid not** refuse poliment : « je regrette, non »."},{"cle":{"type":"trous","trous":[["will be allowed to"]]},"affichage":"will be allowed to","explication":"**will be allowed to** : *can* n’a pas de futur, on emploie *be allowed to*."}]$ex$::jsonb),
  ('430cdc11-f62d-5256-ae2e-c8ed4caa4d71'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les règles du camp d’été","competence":"argumenter","situation":"Lena, 11 ans, est en camp d’été. Elle lit le règlement du camp et écrit à son père.","documents":[{"id":"regles","type":"fiche","modele":"affiche","entete":"Camp Willow","sousTitre":"Rules for campers","emoji":"⛺","lignes":[{"texte":"Campers may use the lake between 2 and 4 p.m.","id":"z1"},{"texte":"You mustn’t swim alone.","id":"z2"},{"texte":"Phones can be used after dinner.","id":"z3"},{"texte":"Under-12s are not allowed to leave the camp.","id":"z4"},{"texte":"Visitors may not enter the tents.","id":"z5"}],"pied":"Have fun!","teinte":"vert","source":"Règlement écrit pour l’exercice"},{"id":"lena","type":"dialogue","modele":"sms","titre":"Lena et son père","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Dad, I’m eleven. Could I go to the village tomorrow?"},{"qui":"Dad","texte":"Let me check the rules at camp."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui exprime l’**interdiction la plus forte**.","aide":"Cherche le modal de l’interdiction stricte.","type":"zone","document":"regles","multiple":false},{"enonce":"Lena a onze ans. D’après le règlement, peut-elle aller au village ?","aide":"Relis la ligne qui parle de l’âge.","type":"choix","options":[{"id":"a","texte":"Oui : les visiteurs peuvent entrer dans les tentes à toute heure"},{"id":"b","texte":"Oui : le lac est ouvert aux campeurs entre 14 h et 16 h"},{"id":"c","texte":"Non : les téléphones sont interdits dans tout le camp"},{"id":"d","texte":"Non : les moins de 12 ans ne peuvent pas quitter le camp"}],"multiple":false},{"enonce":"Complète pour parler du passé.","aide":"Pour une permission au passé, on emploie la forme de *be allowed to*.","type":"trous","segments":["Last year, Lena ",0," use her phone at camp."],"banque":["can’t","mustn’t","may not to","wasn’t allowed to"]},{"enonce":"Remets en ordre la demande « Puis-je utiliser le lac, s’il vous plaît ? ». La phrase commence par May.","aide":"Le modal formel est suivi du sujet puis de la base verbale.","type":"ordre","items":[{"id":"a","texte":"the lake"},{"id":"b","texte":"use"},{"id":"c","texte":"please"},{"id":"d","texte":"May"},{"id":"e","texte":"I"}]},{"enonce":"Associe chaque situation à la bonne formule.","aide":"Pense au registre : ami, adulte, règlement, passé.","type":"association","gauche":[{"id":"g0","texte":"Tu demandes à un professeur de sortir"},{"id":"g1","texte":"Tu demandes le téléphone de ton frère"},{"id":"g2","texte":"Tu accordes une place à un ami"},{"id":"g3","texte":"Un règlement refuse l’entrée"},{"id":"g4","texte":"Tu parles de tes dix ans"}],"droite":[{"id":"d0","texte":"You can sit here."},{"id":"d1","texte":"I wasn’t allowed to go out alone."},{"id":"d2","texte":"Visitors may not enter."},{"id":"d3","texte":"May I leave the room, sir?"},{"id":"d4","texte":"Can I use your phone?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**You mustn’t swim alone** : *mustn’t* interdit fermement."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Under-12s are not allowed to leave the camp** : Lena a 11 ans, donc la réponse est non."},{"cle":{"type":"trous","trous":[["wasn t allowed to"]]},"affichage":"wasn’t allowed to","explication":"**wasn’t allowed to** : au passé, la permission se dit avec *was/were allowed to*."},{"cle":{"type":"ordre","ids":["d","e","b","a","c"]},"explication":"**May I use the lake, please?** *May* + sujet + base verbale."},{"cle":{"type":"association","paires":{"g2":"d0","g4":"d1","g3":"d2","g0":"d3","g1":"d4"}},"explication":"**May** avec un adulte, **can** entre proches, **may not** dans un règlement, **be allowed to** au passé."}]$ex$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un courriel pour la veille d’un contrôle","competence":"comprendre-langue","situation":"Alex a un contrôle de maths demain et n’a rien révisé. Il écrit à une amie, qui lui répond.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Alex asks for advice","blocs":["Hi Mia, I have a maths test tomorrow and I haven’t revised.","Hi Alex! Don’t panic. You should revise tonight and you should go to bed early."],"source":"Courriels écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui sert à **donner un conseil** dans la réponse de Mia.","aide":"Il y en a deux, identiques.","type":"zone","document":"mail","multiple":true},{"enonce":"Complète pour conseiller de ne pas manger trop tard.","aide":"La négation se colle à *should*.","type":"trous","segments":["You ",0," eat so late."],"banque":["shouldn’t","don’t should","should to","not should"]},{"enonce":"Remets en ordre le conseil « Pourquoi ne l’appelles-tu pas ? ». La phrase commence par Why.","aide":"*Why don’t you* est suivi de la base verbale.","type":"ordre","items":[{"id":"a","texte":"call"},{"id":"b","texte":"you"},{"id":"c","texte":"Why"},{"id":"d","texte":"her"},{"id":"e","texte":"don’t"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m22"]},"explication":"**should** exprime le conseil ordinaire : « tu devrais »."},{"cle":{"type":"trous","trous":[["shouldn t"]]},"affichage":"shouldn’t","explication":"**shouldn’t eat** : la négation du conseil est *shouldn’t* + base verbale."},{"cle":{"type":"ordre","ids":["c","e","b","a","d"]},"explication":"**Why don’t you call her?** *Why don’t you* + base verbale propose un conseil sous forme de question."}]$ex$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Kim a raté le bus","competence":"manier-langue","situation":"Kim est arrivée en retard à l’école. Elle raconte sa matinée à Ben, qui lui répond avec des conseils et des reproches.","documents":[{"id":"bus","type":"dialogue","modele":"sms","titre":"Kim et Ben","participants":[{"nom":"Kim","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Kim","texte":"I missed the bus again!"},{"qui":"Ben","texte":"You should have left earlier."},{"qui":"Kim","texte":"I know. Tomorrow I’ll set two alarms."},{"qui":"Ben","texte":"Good plan! If I were you, I would also prepare my bag tonight."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que Ben parle du **passé** (un regret).","aide":"*Should* seul parle du présent ; il faut un second mot.","type":"zone","document":"bus","multiple":false},{"enonce":"Range chaque phrase selon sa force.","aide":"*Should* conseille, *had better* menace un peu, *must* oblige.","type":"categories","categories":[{"id":"c0","texte":"Conseil simple (should)"},{"id":"c1","texte":"Conseil pressant (had better)"},{"id":"c2","texte":"Obligation (must)"}],"items":[{"id":"i0","texte":"You must wear a helmet."},{"id":"i1","texte":"You should rest."},{"id":"i2","texte":"You shouldn’t stay up late."},{"id":"i3","texte":"You’d better rest, or you’ll be ill."},{"id":"i4","texte":"You must rest: the doctor said so."},{"id":"i5","texte":"You’d better not be late."}]},{"enonce":"Complète : à l’écrit, on dit…","aide":"À l’écrit, la forme attendue est la même pour toutes les personnes.","type":"trous","segments":["If I ",0," you, I would apologise."],"banque":["were","was","be","am"]},{"enonce":"Complète.","aide":"La négation se place après *better*.","type":"trous","segments":["You’d better ",0," hurry."],"banque":["never","not","no","don’t"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**should have + participe passé** exprime ce qu’on aurait dû faire. Ici : « tu aurais dû partir plus tôt »."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c1","i4":"c2","i5":"c1"}},"explication":"**Should** : conseil ordinaire ; **had better** : conseil pressant ; **must** : obligation."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : dans « If I were you », la forme irréelle est *were* à toutes les personnes."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**You’d better not hurry** : la négation de *had better* se place après *better*."}]$ex$::jsonb),
  ('00d8c78f-6f58-5ba8-969a-cf590c09a65b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le courrier du cœur","competence":"argumenter","situation":"Sam a oublié l’anniversaire de sa mère et lui a dit une phrase blessante. Il écrit au magazine du collège, et trois amis lui conseillent quelque chose.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Agony Aunt","blocs":["I forgot my mum’s birthday. I didn’t buy a present and I said something rude. I feel terrible. What should I do?"],"source":"Lettre écrite pour l’exercice"},{"id":"avis","type":"tableau","titre":"What his friends say","colonnes":["Friend","Advice"],"lignes":[["Zoe","You should apologise."],["Ben","You’d better apologise before tonight."],["Lily","If I were you, I would write a card."],["Max","Why don’t you cook dinner?"]],"enteteLignes":true,"source":"Réponses écrites pour l’exercice"}],"questions":[{"enonce":"Touche la case qui contient le conseil le plus **pressant**.","aide":"Cherche la tournure qui sous-entend « sinon… ».","type":"zone","document":"avis","multiple":false},{"enonce":"Quelle phrase exprime le regret de Sam ?","aide":"Pour un regret sur le passé : *should have* + participe passé.","type":"choix","options":[{"id":"a","texte":"I shouldn’t have said that."},{"id":"b","texte":"I hadn’t better say that."},{"id":"c","texte":"I should not to say that."},{"id":"d","texte":"I shouldn’t say that."}],"multiple":false},{"enonce":"Complète.","aide":"Il aurait dû, mais il ne l’a pas fait.","type":"trous","segments":["Sam ",0," have bought a present last week."],"banque":["should","may","must","can"]},{"enonce":"Remets en ordre le conseil de Max. La phrase commence par Why.","aide":"Même structure que « Why don’t you call her? ».","type":"ordre","items":[{"id":"a","texte":"you"},{"id":"b","texte":"Why"},{"id":"c","texte":"dinner"},{"id":"d","texte":"cook"},{"id":"e","texte":"don’t"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"*Should* et *had better* ne prennent jamais *to* devant le verbe.","type":"association","gauche":[{"id