  ('791a8ecf-17f0-593e-a963-c5f318cff75b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Cette semaine, tout change","competence":"manier-langue","situation":"Un blog d’élève raconte une semaine qui ne ressemble pas aux autres. Il faut distinguer les habitudes des situations temporaires.","documents":[{"id":"blog","type":"texte","genre":"lettre","titre":"My strange week","blocs":["Usually I walk to school, but this week I’m taking the bus because it’s raining. My sister lives in Leeds, but she is staying with Gran in Bath this week. Gran’s dog is always barking at the postman: it drives us mad!"],"source":"Blog écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce une **habitude**.","aide":"Il indique ce qui se passe d’ordinaire.","type":"zone","document":"blog","multiple":false},{"enonce":"Pourquoi l’auteur écrit-il « this week I’m taking the bus » ?","aide":"Compare avec *Usually I walk*.","type":"choix","options":[{"id":"a","texte":"Parce que c’est une vérité générale"},{"id":"b","texte":"Parce que *take* est un verbe d’état"},{"id":"c","texte":"Parce que c’est une situation temporaire"},{"id":"d","texte":"Parce que c’est un programme fixe"}],"multiple":false},{"enonce":"Complète : un verbe d’état ne prend pas -ING.","aide":"*Know* est un verbe d’état.","type":"trous","segments":["I ",0," the answer."],"banque":["knows","know","knowing","am knowing"]},{"enonce":"Remets en ordre « Elle ne joue pas du piano ». La phrase commence par She.","aide":"La négation se fait avec *do* + *not*.","type":"ordre","items":[{"id":"a","texte":"She"},{"id":"b","texte":"doesn’t"},{"id":"c","texte":"the piano"},{"id":"d","texte":"play"}]},{"enonce":"Que signifie « Gran’s dog is always barking at the postman! » ?","aide":"*Always* + BE + -ING exprime un sentiment.","type":"choix","options":[{"id":"a","texte":"Un agacement devant une habitude"},{"id":"b","texte":"Un horaire fixe prévu à l’avance"},{"id":"c","texte":"Un projet organisé avec d’autres"},{"id":"d","texte":"Une vérité générale, toujours vraie"}],"multiple":false}]}$ex$::jsonb,
