   $ex${"titre":"Le train de 9 h 05","competence":"raisonner","situation":"Ben et Ruby attendent le bus qui les mène à la gare. Ben part à Leeds, et la gare affiche les horaires.","documents":[{"id":"horaires","type":"fiche","modele":"horaires","entete":"Greenfield station","sousTitre":"Timetable","emoji":"🚆","lignes":[{"texte":"Bus 12 – leaves at 7:45","id":"z1"},{"texte":"Train to Leeds – leaves at 9:05","id":"z2"},{"texte":"Museum – opens at 10:00","id":"z3"}],"pied":"Have a good trip!","teinte":"bleu","source":"Horaires écrits pour l’exercice"},{"id":"attente","type":"dialogue","modele":"sms","titre":"Ben et Ruby","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Ruby","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"I’m standing at the bus stop. The bus is late again! We’re meeting Tom at the station for my train to Leeds."},{"qui":"Ruby","texte":"I’m taking my bike today. The bus always arrives late!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Ben va à **Leeds** : touche la ligne de l’horaire qui le concerne.","aide":"Cherche le train.","type":"zone","document":"horaires","multiple":false},{"enonce":"Pourquoi écrit-on « The train leaves at 9:05 » au présent simple ?","aide":"Un train suit un programme régulier.","type":"choix","options":[{"id":"a","texte":"Parce que c’est une situation temporaire"},{"id":"b","texte":"Parce que c’est un horaire fixe"},{"id":"c","texte":"Parce que l’action est en cours"},{"id":"d","texte":"Parce que le train est en retard"}],"multiple":false},{"enonce":"Touche le verbe qui exprime un **projet organisé** (rendez-vous avec Tom).","aide":"Il est en BE + -ING.","type":"zone","document":"attente","multiple":false},{"enonce":"Complète d’après le message de Ruby.","aide":"Elle choisit son vélo pour aujourd’hui seulement.","type":"trous","segments":["Ruby ",0," her bike today."],"banque":["is taking","takes","take","taking"]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Habitude, action en cours, 3e personne, verbe d’état.","type":"association","gauche":[{"id":"g0","texte":"I am going to school every day by bus"},{"id":"g1","texte":"Listen! She sings"},{"id":"g2","texte":"He play football"},{"id":"g3","texte":"I am liking this song"}],"droite":[{"id":"d0","texte":"I like this song"},{"id":"d1","texte":"He plays football"},{"id":"d2","texte":"Listen! She is singing"},{"id":"d3","texte":"I go to school every day by bus"}]}]}$ex$::jsonb,
