  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le samedi de Lily","competence":"comprendre-langue","situation":"Ben demande à sa copine Lily comment s’est passé son samedi. Elle lui répond par message.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Ben et de Lily","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Lily","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Hi Lily! What did you do on Saturday?"},{"qui":"Lily","texte":"I visited my grandma and we made a cake."},{"qui":"Lily","texte":"Then we watched a film together."},{"qui":"Ben","texte":"Sounds lovely!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes au prétérit** qui racontent ce que Lily a fait.","aide":"Ce sont des verbes dans les messages de Lily, pas dans ceux de Ben.","type":"zone","document":"sms","multiple":true},{"enonce":"Dans « What did you do on Saturday? », pourquoi écrit-on **do** et non « did you did » ?","aide":"Regarde quel mot de la question est déjà au passé.","type":"choix","options":[{"id":"a","texte":"Parce que do n’a pas de forme au passé"},{"id":"b","texte":"Parce que did porte déjà la marque du passé"},{"id":"c","texte":"Parce que la question parle du présent"},{"id":"d","texte":"Parce que Ben ne connaît pas la réponse"}],"multiple":false},{"enonce":"Complète le message de Lily.","aide":"Lily raconte un fait passé et terminé.","type":"trous","segments":["Then they ",0," a film together."],"banque":["watched","watching","watch","watches"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m14","m19"]},"explication":"**visited, made, watched** : ce sont les verbes de Lily, tous au prétérit. *Made* est irrégulier (make → made), les deux autres prennent **-ed**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Did porte déjà le passé** : le verbe qui suit revient à la base verbale (*do*), comme dans *Did you go ?*"},{"cle":{"type":"trous","trous":[["watched"]]},"affichage":"watched","explication":"**watched** : verbe régulier, base + **-ed**, pour un fait passé terminé."}]$ex$::jsonb),
  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une carte postale de Cardiff","competence":"manier-langue","situation":"Nora écrit à sa correspondante Jade pour lui raconter une sortie scolaire au pays de Galles.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Hi Jade","blocs":["Hi Jade,","Last Tuesday my class visited Cardiff. We took the train at seven and we saw the castle at noon. I didn’t buy any souvenirs, but my friend Sam bought a mug.","Did you go to Wales last year? Write soon!","Nora"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes irréguliers** au prétérit dans le courriel.","aide":"Un verbe irrégulier ne prend pas -ed : il a sa propre forme.","type":"zone","document":"mail","multiple":true},{"enonce":"Complète la phrase de Nora.","aide":"La phrase est négative et au passé.","type":"trous","segments":["I ",0," buy any souvenirs, but Sam bought a mug."],"banque":["hadn’t","don’t","didn’t","wasn’t"]},{"enonce":"Remets en ordre la question de Nora : « Es-tu allé au pays de Galles ? » La phrase commence par Did.","aide":"Did est suivi du sujet, puis du verbe à la base verbale.","type":"ordre","items":[{"id":"a","texte":"Wales"},{"id":"b","texte":"go"},{"id":"c","texte":"you"},{"id":"d","texte":"Did"},{"id":"e","texte":"to"}]},{"enonce":"Associe chaque erreur d’élève à sa correction.","aide":"Après *did* ou *didn’t*, le verbe est à la base verbale ; avec *last year*, on emploie le prétérit.","type":"association","gauche":[{"id":"g0","texte":"I goed to Cardiff."},{"id":"g1","texte":"We didn’t took the bus."},{"id":"g2","texte":"Did you visited it?"},{"id":"g3","texte":"I have visited it last year."}],"droite":[{"id":"d0","texte":"Did you visit it?"},{"id":"d1","texte":"We didn’t take the bus."},{"id":"d2","texte":"I went to Cardiff."},{"id":"d3","texte":"I visited it last year."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m16","m30"]},"explication":"**took, saw, bought** : ce sont les formes de la 2e colonne de la liste des verbes irréguliers (take → took, see → saw, buy → bought). *Visited* est régulier."},{"cle":{"type":"trous","trous":[["didn t"]]},"affichage":"didn’t","explication":"**didn’t** : la négation du prétérit se fait avec *didn’t* + base verbale (*didn’t buy*)."},{"cle":{"type":"ordre","ids":["d","c","b","e","a"]},"explication":"**Did you go to Wales ?** : did, le sujet, puis le verbe à la base verbale."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"*Go* est irrégulier (**went**) ; après **did / didn’t** on garde la **base verbale** ; et un repère passé comme *last year* impose le **prétérit**."}]$ex$::jsonb),
  ('2fef5a53-98ef-5244-8993-d4d712f5c6bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les souvenirs de Mr Hill","competence":"analyser-texte","situation":"Chloé interroge son grand-père sur sa jeunesse et sur ses débuts de boulanger. Lis le récit de Mr Hill, puis leurs messages.","documents":[{"id":"recit","type":"texte","genre":"article","titre":"Mr Hill remembers","blocs":["When Mr Hill was young, he used to walk to school. Every summer his family played cards on the beach.","In 1985 he moved to Leeds. On his first day at the bakery he opened the shop, put on an apron and baked the first loaves.","He didn’t use to like bread, but now he loves it!"],"source":"Texte écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Chloé et de son grand-père","participants":[{"nom":"Chloe","emoji":"👧","cote":"gauche"},{"nom":"Mr Hill","emoji":"👴","cote":"droite"}],"repliques":[{"qui":"Chloe","texte":"Grandpa, did you have a bike when you were young?"},{"qui":"Mr Hill","texte":"No, I didn’t. I walked everywhere."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce une **habitude passée** qui n’existe plus (forme affirmative).","aide":"Cherche la forme qui précède « to walk ».","type":"zone","document":"recit","multiple":false},{"enonce":"Range chaque phrase selon l’emploi du prétérit qu’elle illustre.","aide":"Une date précise donne une action ponctuelle ; *every summer* annonce une habitude.","type":"categories","categories":[{"id":"c0","texte":"Action ponctuelle"},{"id":"c1","texte":"Suite d’actions"},{"id":"c2","texte":"Habitude passée"}],"items":[{"id":"i0","texte":"He opened the shop, put on an apron and baked the first loaves."},{"id":"i1","texte":"His family played cards on the beach every summer."},{"id":"i2","texte":"She phoned him yesterday."},{"id":"i3","texte":"She opened the window, took a photo and left."},{"id":"i4","texte":"He moved to Leeds in 1985."},{"id":"i5","texte":"He used to walk to school."}]},{"enonce":"Que signifie « He didn’t use to like bread, but now he loves it » ?","aide":"Lis la fin de la phrase : « but now he loves it ».","type":"choix","options":[{"id":"a","texte":"Il n’aime plus du tout le pain aujourd’hui"},{"id":"b","texte":"Il n’aimera pas le pain demain matin"},{"id":"c","texte":"Il n’aimait pas avant, il aime maintenant"},{"id":"d","texte":"Il n’a jamais aimé le pain de sa vie"}],"multiple":false},{"enonce":"Remets en ordre la réponse de Mr Hill : « Je n’avais pas de vélo. » La phrase commence par I.","aide":"La négation du prétérit se fait avec didn’t + base verbale.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"have"},{"id":"c","texte":"bike"},{"id":"d","texte":"I"},{"id":"e","texte":"didn’t"}]},{"enonce":"Complète la phrase d’après le récit.","aide":"Une date précise impose un fait passé terminé.","type":"trous","segments":["In 1985 Mr Hill ",0," to Leeds."],"banque":["moved","was moving","move","used to move"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**used** : *used to* + base verbale dit une habitude du passé qui n’a plus cours."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0","i3":"c1","i4":"c0","i5":"c2"}},"explication":"Une **date précise** = action ponctuelle ; plusieurs actions qui s’enchaînent = **suite d’actions** ; *every summer* ou *used to* = **habitude passée**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Avant il n’aimait pas le pain, maintenant oui** : *didn’t use to* décrit un état passé qui a changé."},{"cle":{"type":"ordre","ids":["d","e","b","a","c"]},"explication":"**I didn’t have a bike.** : *didn’t* + base verbale, comme dans la question de Chloé (*did you have*)."},{"cle":{"type":"trous","trous":[["moved"]]},"affichage":"moved","explication":"**moved** : *in 1985* est un repère passé précis, donc le prétérit simple."}]$ex$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que faisaient-ils à huit heures ?","competence":"comprendre-langue","situation":"Mme Reed enquête sur une bêtise à la maison des élèves. Elle demande à trois élèves ce qu’ils faisaient hier soir.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Ms Reed et de ses élèves","participants":[{"nom":"Ms Reed","emoji":"👩","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"},{"nom":"Leo","emoji":"👦","cote":"droite"},{"nom":"Zoe","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ms Reed","texte":"What were you doing at eight last night?"},{"qui":"Mia","texte":"I was watching TV with my brother."},{"qui":"Leo","texte":"I was cooking pasta."},{"qui":"Zoe","texte":"I was reading a book in my room."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes en -ING** qui disent ce que faisaient les élèves.","aide":"Ils suivent « was » dans les réponses.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète d’après le message de Mia.","aide":"Le sujet est pluriel : Mia and her brother.","type":"trous","segments":["Mia and her brother ",0," watching TV."],"banque":["was","did","are","were"]},{"enonce":"Remets en ordre la question de Mme Reed : « Que faisait Leo ? » La phrase commence par What.","aide":"was se place avant le sujet.","type":"ordre","items":[{"id":"a","texte":"was"},{"id":"b","texte":"What"},{"id":"c","texte":"Leo"},{"id":"d","texte":"doing"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m17","m21"]},"explication":"**watching, cooking, reading** : *was* + verbe en **-ING** décrit une action en cours à un moment du passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : avec un sujet pluriel (*Mia and her brother*), on emploie **were** devant le verbe en -ING."},{"cle":{"type":"ordre","ids":["b","a","c","d"]},"explication":"**What was Leo doing ?** : mot interrogatif, *was*, le sujet, puis le verbe en -ING."}]$ex$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le témoin du parc","competence":"analyser-texte","situation":"Un policier a recueilli la déposition d’un témoin qui rentrait chez lui à pied. Observe ce qui décrit le décor et ce qui survient.","documents":[{"id":"depo","type":"texte","genre":"article","titre":"Witness statement","blocs":["It was six o’clock and I was walking home. Rain was falling and the park was empty.","Suddenly a man ran out of the bushes and dropped his bag. I shouted, and he disappeared."],"source":"Déposition écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes d’événement** au prétérit simple.","aide":"Cherche les actions courtes qui surviennent, pas celles qui décrivent le décor.","type":"zone","document":"depo","multiple":true},{"enonce":"Range chaque morceau du récit : décor ou événement ?","aide":"Le décor dure ; l’événement survient.","type":"categories","categories":[{"id":"c0","texte":"Décor (BE + -ING)"},{"id":"c1","texte":"Événement (prétérit simple)"}],"items":[{"id":"i0","texte":"He disappeared"},{"id":"i1","texte":"He dropped his bag"},{"id":"i2","texte":"I was walking home"},{"id":"i3","texte":"A man ran out of the bushes"},{"id":"i4","texte":"Rain was falling"}]},{"enonce":"Complète comme dans la déposition.","aide":"Quelle conjonction introduit l’événement court ?","type":"trous","segments":["I was walking home ",0," it started to rain."],"banque":["because","while","until","when"]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Vérifie l’auxiliaire, le -ING, puis les verbes d’état.","type":"association","gauche":[{"id":"g0","texte":"They was playing."},{"id":"g1","texte":"I was watch TV."},{"id":"g2","texte":"I was knowing the answer."},{"id":"g3","texte":"When I was arriving, he left."}],"droite":[{"id":"d0","texte":"I was watching TV."},{"id":"d1","texte":"I knew the answer."},{"id":"d2","texte":"When I arrived, he was leaving."},{"id":"d3","texte":"They were playing."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20","m26","m30","m33"]},"explication":"**ran, dropped, shouted, disappeared** : les événements brefs sont au prétérit simple ; le décor (*was walking, was falling*) est en BE + -ING."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Le **décor** dure et encadre : BE + -ING. L’**événement** survient d’un coup : prétérit simple."},{"cle":{"type":"trous","trous":[["when"]]},"affichage":"when","explication":"**when** introduit l’action courte qui survient ; **while** s’emploie devant l’action longue."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**were** avec *they* ; **-ING** après was/were ; *know* est un verbe d’état (pas de -ING) ; l’arrivée brève est au prétérit simple."}]$ex$::jsonb),
  ('3055a332-e131-5e86-9f5c-31f982d631fc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’alibi de la bibliothèque","competence":"argumenter","situation":"Un livre précieux a disparu de la bibliothèque. L’inspecteur Reed interroge deux élèves, puis compare avec le journal de la caméra de surveillance.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de l’inspecteur et des élèves","participants":[{"nom":"Inspector Reed","emoji":"🕵","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inspector Reed","texte":"Where were you at eight twenty last night?"},{"qui":"Mia","texte":"I was reading in the library. I stayed there until nine."},{"qui":"Leo","texte":"I was playing football in the park."}],"source":"Messages écrits pour l’exercice"},{"id":"cam","type":"tableau","titre":"Camera log","colonnes":["Time","Place","What the camera shows"],"lignes":[["7.55","Library","Mia goes in"],["8.10","Library","Mia leaves"],["8.15","Park","Leo plays football"],["8.30","Park","Leo and Zoe talk"]],"enteteLignes":true,"source":"Journal écrit pour l’exercice"}],"questions":[{"enonce":"En croisant les deux documents, qui ne dit pas la vérité ?","aide":"Compare l’heure donnée par Mia avec ce que montre la caméra de la bibliothèque.","type":"choix","options":[{"id":"a","texte":"Mia"},{"id":"b","texte":"Aucun des deux"},{"id":"c","texte":"Leo"},{"id":"d","texte":"Mia et Leo"}],"multiple":false},{"enonce":"Touche les **deux mots** qui forment l’action en cours dans la réponse de Leo.","aide":"Le prétérit en BE + -ING = was / were + verbe en -ING.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète la conclusion de l’inspecteur.","aide":"Le premier verbe raconte un fait passé daté ; le second nie une action en cours.","type":"trous","segments":["At 8.10 Mia ",0," the library, so she ",1," reading there at 8.20."],"banque":["wasn’t","left","isn’t","leaves"]},{"enonce":"Remets en ordre la question de l’inspecteur. La phrase commence par Where.","aide":"Après le mot interrogatif, were se place avant le sujet.","type":"ordre","items":[{"id":"a","texte":"eight"},{"id":"b","texte":"Where"},{"id":"c","texte":"were"},{"id":"d","texte":"at"},{"id":"e","texte":"twenty"},{"id":"f","texte":"you"}]},{"enonce":"Associe chaque phrase à ce qu’elle dit.","aide":"Le prétérit simple clôt l’action ; BE + -ING la décrit en cours.","type":"association","gauche":[{"id":"g0","texte":"I watched a film."},{"id":"g1","texte":"I was watching a film."},{"id":"g2","texte":"She was cooking while he was doing his homework."}],"droite":[{"id":"d0","texte":"On ne dit pas si j’ai fini."},{"id":"d1","texte":"Le film est terminé."},{"id":"d2","texte":"Deux actions en même temps."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"**Mia** : elle dit qu’elle lisait à la bibliothèque à 8 h 20, mais la caméra la montre sortant à 8 h 10. Leo joue au football au parc à 8 h 15, ce qui est compatible avec son récit."},{"cle":{"type":"zone","ids":["m20","m21"]},"explication":"**was playing** : *was* + verbe en **-ING** pour une action en cours à 8 h 20."},{"cle":{"type":"trous","trous":[["left"],["wasn t"]]},"affichage":"left · wasn’t","explication":"**left** : prétérit simple de *leave* (fait passé daté, 8 h 10) ; **wasn’t** reading : négation du prétérit en BE + -ING."},{"cle":{"type":"ordre","ids":["b","c","f","d","a","e"]},"explication":"**Where were you at eight twenty ?** : mot interrogatif, *were*, le sujet, puis l’heure."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le prétérit simple présente l’action comme **finie** ; BE + -ING la montre **en cours** ; *while* relie deux actions **simultanées**."}]$ex$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Rome","competence":"comprendre-langue","situation":"Hugo passe ses vacances en Italie. Il écrit à sa grand-mère ce qu’il a déjà fait.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Postcard from Rome","blocs":["Dear Granny,","I have arrived in Rome! I have already visited the Colosseum and I have eaten two ice creams. I haven’t seen the Vatican yet.","Love, Hugo"],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre participes passés** de la carte.","aide":"Ils suivent have / haven’t.","type":"zone","document":"carte","multiple":true},{"enonce":"Que signifie « I haven’t seen the Vatican yet » ?","aide":"*Yet* est placé à la fin d’une négation.","type":"choix","options":[{"id":"a","texte":"Je ne le verrai plus"},{"id":"b","texte":"Je ne l’ai pas vu hier"},{"id":"c","texte":"Je ne l’ai jamais vu et je n’irai pas"},{"id":"d","texte":"Je ne l’ai pas encore vu"}],"multiple":false},{"enonce":"Complète d’après la carte.","aide":"Le marqueur se place entre has et le participe passé.","type":"trous","segments":["Hugo has ",0," visited the Colosseum."],"banque":["yesterday","ago","yet","already"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m10","m16","m22"]},"explication":"**arrived, visited, eaten, seen** : le present perfect = *have / has* + participe passé."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Je ne l’ai pas encore vu** : *not … yet* = « pas encore »."},{"cle":{"type":"trous","trous":[["already"]]},"affichage":"already","explication":"**already** se place entre l’auxiliaire et le participe passé ; *ago* et *yesterday* sont des repères datés (prétérit)."}]$ex$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les nouveaux voisins de Maple Street","competence":"manier-langue","situation":"Le journal de quartier présente les habitants de Maple Street et depuis quand ils y vivent. Aujourd’hui, nous sommes en 2025.","documents":[{"id":"rue","type":"texte","genre":"article","titre":"Maple Street news","blocs":["New neighbours at last! Ava has lived at number 4 since 2020. Ben has lived at number 6 for three months.","Carla has had her flower shop on the corner since January, and Dev has repaired bikes in the street for ten years."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui introduisent un **point de départ**.","aide":"Ils sont suivis d’une date ou d’un mois.","type":"zone","document":"rue","multiple":true},{"enonce":"Complète la phrase.","aide":"2020 est une date ; three months est une durée.","type":"trous","segments":["Ava has lived here ",0," 2020, but Ben has lived here ",1," three months."],"banque":["ago","for","from","since"]},{"enonce":"Remets en ordre : « Dev habite ici depuis 2015. » La phrase commence par Dev.","aide":"Le present perfect = has + participe passé.","type":"ordre","items":[{"id":"a","texte":"since 2015"},{"id":"b","texte":"has"},{"id":"c","texte":"here"},{"id":"d","texte":"lived"},{"id":"e","texte":"Dev"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Avec since / for, le présent français devient present perfect ; avec yesterday, c’est le prétérit.","type":"association","gauche":[{"id":"g0","texte":"I live here since 2020."},{"id":"g1","texte":"I am here since Monday."},{"id":"g2","texte":"She have finished."},{"id":"g3","texte":"I have seen him yesterday."}],"droite":[{"id":"d0","texte":"I have lived here since 2020."},{"id":"d1","texte":"I saw him yesterday."},{"id":"d2","texte":"She has finished."},{"id":"d3","texte":"I have been here since Monday."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m30"]},"explication":"**since** introduit un point de départ (*since 2020, since January*) ; **for** introduit une durée."},{"cle":{"type":"trous","trous":[["since"],["for"]]},"affichage":"since · for","explication":"**since** 2020 (point de départ), **for** three months (durée)."},{"cle":{"type":"ordre","ids":["e","b","d","c","a"]},"explication":"**Dev has lived here since 2015.** : le français dit « habite » au présent, l’anglais emploie le present perfect."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**Depuis** se dit avec le **present perfect** (*have lived, have been*) ; **has** avec she/he/it ; un repère comme *yesterday* impose le **prétérit**."}]$ex$::jsonb),
  ('9d02a039-f2ca-5e68-affe-5f4f34deabb6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Candidat pour le camp d’été","competence":"argumenter","situation":"Sam répond à une annonce qui recherche des animateurs pour un camp. Lis l’annonce, puis sa lettre de motivation.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Camp helpers wanted","sousTitre":"Sunny Bay Camp — July","emoji":"🏕","lignes":[{"texte":"Have you ever worked with children?","id":"z1"},{"texte":"Have you ever taught a sport?","id":"z2"},{"texte":"Can you start on 1 July?","id":"z3"}],"pied":"Write to Mr Evans","source":"Affiche écrite pour l’exercice"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Sam’s letter","blocs":["Dear Mr Evans,","I saw your poster yesterday. I have worked with children since 2023: I have coached a football team for two years. Last summer I taught swimming at a pool. I have never been late for work.","I can start on 1 July. Best wishes, Sam"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes de Sam au prétérit** (repère passé précis).","aide":"Cherche *yesterday* et *last summer*.","type":"zone","document":"lettre","multiple":true},{"enonce":"Sam écrit « Last summer I taught swimming ». Touche la question de l’affiche à laquelle cette phrase répond.","aide":"Nager est un sport.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète la phrase de Sam.","aide":"Yesterday est un repère passé précis.","type":"trous","segments":["Sam ",0," your poster yesterday."],"banque":["sees","have seen","saw","has seen"]},{"enonce":"Remets en ordre : « Il entraîne une équipe depuis deux ans. » La phrase commence par He.","aide":"Une action commencée dans le passé qui continue se dit au present perfect.","type":"ordre","items":[{"id":"a","texte":"a team"},{"id":"b","texte":"He"},{"id":"c","texte":"coached"},{"id":"d","texte":"has"},{"id":"e","texte":"for two years"}]},{"enonce":"Associe chaque phrase à ce qu’elle exprime.","aide":"Cherche le lien avec le présent, ou la date précise.","type":"association","gauche":[{"id":"g0","texte":"I have lost my phone."},{"id":"g1","texte":"I lost my phone last night."},{"id":"g2","texte":"I have lived here for years."}],"droite":[{"id":"d0","texte":"Situation qui continue"},{"id":"d1","texte":"Résultat présent : je ne l’ai plus"},{"id":"d2","texte":"Fait daté, coupé du présent"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m27"]},"explication":"**saw** (*yesterday*) et **taught** (*last summer*) : un repère passé précis impose le prétérit."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Have you ever taught a sport ?** : *swimming* est un sport que Sam a enseigné."},{"cle":{"type":"trous","trous":[["saw"]]},"affichage":"saw","explication":"**saw** : avec *yesterday*, on emploie le prétérit, pas le present perfect."},{"cle":{"type":"ordre","ids":["b","d","c","a","e"]},"explication":"**He has coached a team for two years.** : *for* + durée avec le present perfect."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le **present perfect** relie le passé au présent (résultat, durée) ; le **prétérit** raconte un fait daté, terminé."}]$ex$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le train de 8 heures","competence":"comprendre-langue","situation":"Nina arrive à la gare et rate son train. Elle prévient son père par message.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Nina et de son père","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"I arrived at the station at 8.05, but the train had already left!"},{"qui":"Dad","texte":"Oh no! I thought you had bought a ticket for the 8.30 train."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux auxiliaires** du past perfect.","aide":"Il est identique à toutes les personnes.","type":"zone","document":"sms","multiple":true},{"enonce":"Quelle action s’est passée en premier ?","aide":"L’action au past perfect est la plus ancienne.","type":"choix","options":[{"id":"a","texte":"Le train est parti avant l’arrivée de Nina"},{"id":"b","texte":"Les deux en même temps"},{"id":"c","texte":"On ne peut pas le savoir"},{"id":"d","texte":"Nina est arrivée avant le départ du train"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le train est parti avant son arrivée.","type":"trous","segments":["When Nina arrived, the train ",0," already left."],"banque":["has","had","is","was"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m19"]},"explication":"**had** : le past perfect se forme avec *had* + participe passé (*had left, had bought*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le train est parti avant son arrivée** : le past perfect (*had left*) marque l’action antérieure."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** + participe passé pour une action antérieure à une autre action passée."}]$ex$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi Maya était bouleversée","competence":"analyser-texte","situation":"Maya arrive en retard à un contrôle. Observe l’ordre dans lequel les événements se sont déroulés.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Maya’s bad morning","blocs":["When Maya got to school, the test had already started. She had forgotten her alarm clock and she hadn’t studied enough.","After she had calmed down, she sat down and did her best."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre participes passés** du past perfect.","aide":"Cherche les verbes précédés de had ou hadn’t.","type":"zone","document":"recit","multiple":true},{"enonce":"Range chaque fait : le plus ancien ou le plus récent ?","aide":"Le past perfect marque ce qui s’est passé avant.","type":"categories","categories":[{"id":"c0","texte":"Action la plus ancienne (past perfect)"},{"id":"c1","texte":"Action la plus récente (prétérit)"}],"items":[{"id":"i0","texte":"Maya forgets her alarm clock."},{"id":"i1","texte":"The test starts."},{"id":"i2","texte":"Maya gets to school."},{"id":"i3","texte":"Maya sits down."},{"id":"i4","texte":"Maya calms down."},{"id":"i5","texte":"Maya does her best."}]},{"enonce":"Complète d’après le récit.","aide":"Elle n’avait pas étudié avant le contrôle.","type":"trous","segments":["Maya was upset because she ",0," studied enough."],"banque":["hasn’t","didn’t","hadn’t","wasn’t"]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Après had, on met le participe passé.","type":"association","gauche":[{"id":"g0","texte":"She was gone when I arrived."},{"id":"g1","texte":"I had went."},{"id":"g2","texte":"He had finish."},{"id":"g3","texte":"I had never saw snow."}],"droite":[{"id":"d0","texte":"She had gone when I arrived."},{"id":"d1","texte":"I had gone."},{"id":"d2","texte":"I had never seen snow."},{"id":"d3","texte":"He had finished."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m12","m19","m24"]},"explication":"**started, forgotten, studied, calmed** : *had* + participe passé pour les actions antérieures."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Le **past perfect** (*had started, had forgotten, had calmed*) marque ce qui est arrivé **avant** ; le prétérit raconte la suite."},{"cle":{"type":"trous","trous":[["hadn t"]]},"affichage":"hadn’t","explication":"**hadn’t** : la négation du past perfect se forme avec *hadn’t* + participe passé."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Le plus-que-parfait français se traduit par **had** + **participe passé** (3e colonne : go → gone, see → seen), jamais par *was*."}]$ex$::jsonb),
  ('bfd40b71-74c1-5bb4-9270-f8341862c0ca'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vol à la bibliothèque","competence":"argumenter","situation":"Un matin, le bibliothécaire découvre un vol. Compare son témoignage avec le tableau reconstitué par la police.","documents":[{"id":"temoin","type":"texte","genre":"article","titre":"Mr Brown’s statement","blocs":["When I opened the library at eight, someone had broken a window. The thief had taken two old maps, but he hadn’t touched the computers. A neighbour told me she had heard a noise at midnight."],"source":"Témoignage écrit pour l’exercice"},{"id":"nuit","type":"tableau","titre":"The night of the robbery","colonnes":["Time","What happened"],"lignes":[["8 a.m.","The librarian opens the door and sees the broken window"],["10 p.m.","The librarian locks the door"],["Midnight","A neighbour hears a noise"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre participes passés** du past perfect dans le témoignage.","aide":"Ils suivent had ou hadn’t.","type":"zone","document":"temoin","multiple":true},{"enonce":"Range dans l’ordre chronologique les trois faits du tableau.","aide":"8 a.m. est le matin suivant.","type":"ordre","items":[{"id":"a","texte":"A neighbour heard a noise."},{"id":"b","texte":"The librarian locked the door."},{"id":"c","texte":"The librarian saw the broken window."}]},{"enonce":"Complète d’après les deux documents.","aide":"Les deux actions précèdent 8 heures.","type":"trous","segments":["When the librarian opened the door at eight, the thief ",0," already left, but the police ",1," arrived yet."],"banque":["has","hadn’t","had","wasn’t"]},{"enonce":"Pourquoi Mr Brown dit-il « someone had broken a window » ?","aide":"Pense à l’ordre : fenêtre cassée, puis il ouvre.","type":"choix","options":[{"id":"a","texte":"Elle était cassée avant son arrivée"},{"id":"b","texte":"Il a cassé la fenêtre en ouvrant"},{"id":"c","texte":"Le past perfect remplace le futur"},{"id":"d","texte":"La fenêtre est cassée en ce moment"}],"multiple":false},{"enonce":"Associe chaque phrase à son sens.","aide":"Le past perfect marque l’antériorité ; had just = venait de.","type":"association","gauche":[{"id":"g0","texte":"When I arrived, the film started."},{"id":"g1","texte":"When I arrived, the film had started."},{"id":"g2","texte":"He had just left when she phoned."},{"id":"g3","texte":"I had never seen snow before."}],"droite":[{"id":"d0","texte":"Le film avait déjà commencé."},{"id":"d1","texte":"Le film a commencé à mon arrivée."},{"id":"d2","texte":"Il venait de partir quand elle a téléphoné."},{"id":"d3","texte":"Je n’avais jamais vu de neige avant."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m15","m22","m31"]},"explication":"**broken, taken, touched, heard** : *had* + participe passé pour ce qui s’est passé avant 8 heures."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**10 p.m. → midnight → 8 a.m.** : le bibliothécaire ferme, le voisin entend un bruit, puis le matin le bibliothécaire voit la fenêtre brisée."},{"cle":{"type":"trous","trous":[["had"],["hadn t"]]},"affichage":"had · hadn’t","explication":"**had** already left (le voleur est parti avant) et **hadn’t** arrived (la police n’est pas encore arrivée) : *had* / *hadn’t* + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**La fenêtre était cassée avant qu’il ouvre** : le past perfect marque l’action antérieure."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**Past perfect** : action déjà accomplie avant l’autre. *Had just* + participe = « venir de » au passé."}]$ex$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets du week-end","competence":"comprendre-langue","situation":"Ella et Jack parlent de leur samedi par message. Lis comment chacun parle de l’avenir.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Ella et de Jack","participants":[{"nom":"Ella","emoji":"👧","cote":"gauche"},{"nom":"Jack","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ella","texte":"What are you doing on Saturday?"},{"qui":"Jack","texte":"I’m meeting Sam at five. We’re going to see a film."},{"qui":"Ella","texte":"Nice! I’ll come with you!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe en **BE + -ING** qui exprime un **rendez-vous organisé**.","aide":"Cherche le verbe en -ING qui suit « I’m ».","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Ella dit-elle « I’ll come with you! » ?","aide":"Pense à ce qui s’est passé juste avant sa phrase.","type":"choix","options":[{"id":"a","texte":"Elle avait déjà tout organisé"},{"id":"b","texte":"Elle prédit à partir d’un indice"},{"id":"c","texte":"Elle décide à l’instant de venir"},{"id":"d","texte":"Elle donne un horaire officiel"}],"multiple":false},{"enonce":"Complète d’après le message de Jack.","aide":"Le sujet est we.","type":"trous","segments":["We ",0," going to see a film."],"banque":["is","am","are","will"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**meeting** : *I’m meeting Sam at five* est un rendez-vous organisé avec une heure précise."},{"cle":{"type":"choix","ids":["c"]},"explication":"**will** exprime une décision prise **au moment de parler**."},{"cle":{"type":"trous","trous":[["are"]]},"affichage":"are","explication":"**are** : *be going to* se conjugue avec le verbe *be* (*we are going to*)."}]$ex$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ruby part pour Édimbourg","competence":"manier-langue","situation":"Ruby prépare son voyage vers l’Écosse. Elle écrit à sa grand-mère, avec l’horaire de son train sous les yeux.","documents":[{"id":"horaire","type":"fiche","modele":"horaires","entete":"Train timetable","sousTitre":"London → Edinburgh","emoji":"🚆","lignes":[{"texte":"Leaves London","valeur":"7.15","id":"z1"},{"texte":"Arrives Edinburgh","valeur":"11.50","id":"z2"}],"pied":"Daily service","source":"Horaire écrit pour l’exercice"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Ruby’s message","blocs":["Hi Gran,","Next summer I’m going to visit Edinburgh! My train leaves very early, so I’m going to be tired. I’m meeting Aunt Meg at the station, and I’ll text you when I arrive.","Ruby"],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe que Ruby met au **présent simple** pour parler d’un horaire.","aide":"Cherche le verbe qui parle de son train.","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque phrase selon la forme du futur qu’elle illustre.","aide":"Décision immédiate, intention ou indice, rendez-vous, horaire.","type":"categories","categories":[{"id":"c0","texte":"will"},{"id":"c1","texte":"be going to"},{"id":"c2","texte":"BE + -ING"},{"id":"c3","texte":"Présent simple"}],"items":[{"id":"i0","texte":"We’re leaving on Friday — the tickets are booked."},{"id":"i1","texte":"The train leaves at 7.15."},{"id":"i2","texte":"I’m going to learn the guitar."},{"id":"i3","texte":"The film starts at eight."},{"id":"i4","texte":"The phone’s ringing — I’ll answer it!"},{"id":"i5","texte":"Look at those clouds — it’s going to rain."},{"id":"i6","texte":"I’m having lunch with Meg at noon."},{"id":"i7","texte":"I think it will be sunny."}]},{"enonce":"Complète la phrase de Ruby.","aide":"Après une conjonction de temps, on emploie le présent.","type":"trous","segments":["I’ll text you as soon as I ",0," in Edinburgh."],"banque":["will arrive","am arriving","arrive","arrived"]},{"enonce":"Remets en ordre la phrase de Ruby qui donne l’heure du train (voir l’horaire) : « Mon train part à 7 h 15. » La phrase commence par My.","aide":"L’heure vient de la fiche d’horaires.","type":"ordre","items":[{"id":"a","texte":"My"},{"id":"b","texte":"7.15"},{"id":"c","texte":"train"},{"id":"d","texte":"leaves"},{"id":"e","texte":"at"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**leaves** : un horaire officiel se dit au présent simple."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c3","i2":"c1","i3":"c3","i4":"c0","i5":"c1","i6":"c2","i7":"c0"}},"explication":"**will** : décision immédiate ou prédiction ; **be going to** : intention ou indice visible ; **BE + -ING** : rendez-vous organisé ; **présent simple** : horaire officiel."},{"cle":{"type":"trous","trous":[["arrive"]]},"affichage":"arrive","explication":"**arrive** : après *as soon as*, *when*, *before*…, l’anglais emploie le **présent**, jamais *will*."},{"cle":{"type":"ordre","ids":["a","c","d","e","b"]},"explication":"**My train leaves at 7.15.** : présent simple pour un horaire officiel."}]$ex$::jsonb),
  ('5f715fe1-08d3-5632-adbb-436ee655a8cd'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"La fête sous la pluie","competence":"argumenter","situation":"Zoé et Noé préparent une fête d’anniversaire. Lis leurs messages, puis la météo du samedi.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Zoé et de Noé","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"My party starts at three on Saturday!"},{"qui":"Noah","texte":"Great! I’m bringing the speakers."},{"qui":"Zoe","texte":"Look at those black clouds: it’s going to rain."},{"qui":"Noah","texte":"Then we’ll play inside. I can’t lift the speakers alone, though."},{"qui":"Zoe","texte":"Don’t worry, I’ll help you."}],"source":"Messages écrits pour l’exercice"},{"id":"meteo","type":"fiche","modele":"panneau","entete":"Weather forecast","sousTitre":"Saturday","emoji":"🌦","lignes":[{"texte":"Morning: sunny","id":"z1"},{"texte":"Afternoon: heavy rain","id":"z2"},{"texte":"Evening: dry and cool","id":"z3"}],"pied":"Source : prévisions écrites pour l’exercice","source":"Prévisions écrites pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que Zoé **prédit la pluie d’après un indice visible**.","aide":"Cherche la forme qui suit « it’s ».","type":"zone","document":"sms","multiple":false},{"enonce":"La fête commence à 15 h. Touche la ligne de la météo qui justifie l’avertissement de Zoé.","aide":"Trois heures de l’après-midi, c’est quel moment de la journée ?","type":"zone","document":"meteo","multiple":false},{"enonce":"Associe chaque phrase du dialogue à la forme du futur qu’elle illustre.","aide":"Horaire, organisation, indice, décision immédiate.","type":"association","gauche":[{"id":"g0","texte":"My party starts at three."},{"id":"g1","texte":"I’m bringing the speakers."},{"id":"g2","texte":"It’s going to rain."},{"id":"g3","texte":"I’ll help you."}],"droite":[{"id":"d0","texte":"BE + -ING : une chose organisée"},{"id":"d1","texte":"Présent simple : un horaire"},{"id":"d2","texte":"be going to : un indice visible"},{"id":"d3","texte":"will : une offre sur le moment"}]},{"enonce":"Complète la phrase de Zoé.","aide":"Après as soon as, pas de will.","type":"trous","segments":["I’ll call you as soon as the rain ",0,"."],"banque":["stopping","will stop","stopped","stops"]},{"enonce":"Noah veut dire « J’allais apporter les enceintes, mais j’ai oublié. » Quelle phrase est correcte ?","aide":"Une intention qui n’a pas eu lieu se dit au passé.","type":"choix","options":[{"id":"a","texte":"I bring the speakers, but I forgot."},{"id":"b","texte":"I was going to bring the speakers, but I forgot."},{"id":"c","texte":"I will bring the speakers, but I forgot."},{"id":"d","texte":"I am going to bring the speakers, but I forgot."}],"multiple":false},{"enonce":"Remets en ordre la demande de Noé : « Tu veux bien m’aider à porter les enceintes ? » La phrase commence par Will.","aide":"Une demande se fait avec will, puis le sujet.","type":"ordre","items":[{"id":"a","texte":"carry"},{"id":"b","texte":"the speakers"},{"id":"c","texte":"help"},{"id":"d","texte":"Will"},{"id":"e","texte":"you"},{"id":"f","texte":"me"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**going** : *be going to* est la forme d’une prédiction fondée sur un indice présent (les nuages)."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Afternoon: heavy rain** : la fête a lieu l’après-midi, c’est donc le moment où la pluie est annoncée."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Chaque forme répond à un **degré de préparation** : horaire officiel, rendez-vous organisé, intention ou indice, décision sur le moment."},{"cle":{"type":"trous","trous":[["stops"]]},"affichage":"stops","explication":"**stops** : après *as soon as*, le présent exprime l’avenir."},{"cle":{"type":"choix","ids":["b"]},"explication":"**I was going to … but I forgot** : *was / were going to* exprime une intention du passé qui n’a pas été réalisée."},{"cle":{"type":"ordre","ids":["d","e","c","f","a","b"]},"explication":"**Will you help me carry the speakers ?** : *will* sert aussi à faire une demande."}]$ex$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Si demain il pleut…","competence":"comprendre-langue","situation":"La classe de Mina prépare son plan pour samedi : une activité s’il pleut, une autre s’il fait beau.","documents":[{"id":"plan","type":"texte","genre":"article","titre":"Our weather plan","blocs":["If it rains on Saturday, we will watch a film. If it is sunny, we will play outside."],"source":"Plan écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** qui suivent « if ».","aide":"Ils sont au présent.","type":"zone","document":"plan","multiple":true},{"enonce":"Quelle structure ce plan utilise-t-il ?","aide":"Ce qui est envisagé peut vraiment arriver.","type":"choix","options":[{"id":"a","texte":"if + présent, will + base verbale"},{"id":"b","texte":"if + past perfect, would have + participe"},{"id":"c","texte":"if + will, would + base verbale"},{"id":"d","texte":"if + prétérit, would + base verbale"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"On ne met jamais will après if.","type":"trous","segments":["If it ",0," on Sunday, we will stay home."],"banque":["will rain","would rain","rains","rained"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m12"]},"explication":"**rains** et **is** : après *if*, on emploie le **présent simple**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**if + présent, will + base verbale** : c’est la condition de type 1, le possible."},{"cle":{"type":"trous","trous":[["rains"]]},"affichage":"rains","explication":"**rains** : présent simple après *if* ; le *will* est dans la principale."}]$ex$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Si j’étais directrice…","competence":"manier-langue","situation":"Léna écrit au proviseur pour lui dire ce qu’elle changerait si elle dirigeait le collège.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lena’s letter","blocs":["Dear Mr Hall,","If I were the headteacher, I would build a swimming pool. If we had a longer lunch break, we would play football every day. I wish I could change the rules!","Yours, Lena"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au prétérit** qui suivent « if ».","aide":"Après if, on n’écrit ni will ni would.","type":"zone","document":"lettre","multiple":true},{"enonce":"Range chaque phrase selon son type de condition.","aide":"Regarde le temps du verbe après if.","type":"categories","categories":[{"id":"c0","texte":"Type 1 : possible"},{"id":"c1","texte":"Type 2 : irréel du présent"},{"id":"c2","texte":"Type 3 : irréel du passé"}],"items":[{"id":"i0","texte":"If I were you, I would apologise."},{"id":"i1","texte":"If it snows, we will make a snowman."},{"id":"i2","texte":"If he had known, he would have come."},{"id":"i3","texte":"If you come, we will play tennis."},{"id":"i4","texte":"If I had a dog, I would walk it every day."},{"id":"i5","texte":"If she had studied, she would have passed."}]},{"enonce":"Complète la phrase de Léna.","aide":"Le prétérit de be se dit were à toutes les personnes dans cette structure.","type":"trous","segments":["If I ",0," the headteacher, I would build a pool."],"banque":["were","am","would be","will be"]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Jamais will ni would après if.","type":"association","gauche":[{"id":"g0","texte":"If I would have money, I would buy it."},{"id":"g1","texte":"If it will rain, I stay home."},{"id":"g2","texte":"If I had known, I would come."},{"id":"g3","texte":"If I was you…"}],"droite":[{"id":"d0","texte":"If I had money, I would buy it."},{"id":"d1","texte":"If I had known, I would have come."},{"id":"d2","texte":"If it rains, I will stay home."},{"id":"d3","texte":"If I were you…"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m16"]},"explication":"**were** et **had** : dans la condition de type 2, la proposition en *if* est au **prétérit** ; *were* à toutes les personnes."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c0","i4":"c1","i5":"c2"}},"explication":"**Présent / will** : possible ; **prétérit / would** : irréel du présent ; **past perfect / would have** : irréel du passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : avec *if*, on emploie *were* pour toutes les personnes dans la structure de l’irréel du présent."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"On n’écrit jamais **will** ni **would** après *if* ; chaque type a sa structure ; à l’écrit on garde **were**."}]$ex$::jsonb),
  ('863ebe89-2a1a-53d5-8e0c-551fe22d9df9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les regrets de Tom","competence":"argumenter","situation":"Tom a raté un examen. Il note ses regrets dans son journal, puis il en parle avec Inès.","documents":[{"id":"journal","type":"texte","genre":"lettre","titre":"Tom’s diary","blocs":["I didn’t study, so I failed the exam. If I had studied, I would have passed. If I hadn’t missed the bus, I would have arrived on time."],"source":"Journal écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Tom et d’Inès","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Ines","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"I failed again. What can I do?"},{"qui":"Ines","texte":"If I were you, I would ask for another test."},{"qui":"Tom","texte":"If the teacher says yes, I will study every night."},{"qui":"Ines","texte":"Good! You will fail again unless you work."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux auxiliaires** qui suivent « if » dans le journal de Tom.","aide":"La condition de type 3 emploie le past perfect après if.","type":"zone","document":"journal","multiple":true},{"enonce":"Que signifie « If I had studied, I would have passed » ?","aide":"L’irréel du passé exprime un regret.","type":"choix","options":[{"id":"a","texte":"J’ai étudié et j’ai réussi"},{"id":"b","texte":"Je n’ai pas étudié et j’ai échoué"},{"id":"c","texte":"Je n’ai pas étudié mais j’ai réussi"},{"id":"d","texte":"Je n’étudie pas et j’échouerai"}],"multiple":false},{"enonce":"Complète d’après les messages.","aide":"Le premier blanc est une condition de type 2 ; le second veut dire « à moins que ».","type":"trous","segments":["If Ines ",0," Tom, she would ask for another test. Tom will fail again ",1," he works."],"banque":["am","were","unless","until"]},{"enonce":"Associe chaque phrase à son sens.","aide":"Would sert aussi hors des phrases en if.","type":"association","gauche":[{"id":"g0","texte":"I would like a coffee."},{"id":"g1","texte":"I would rather stay."},{"id":"g2","texte":"I wish I could come."},{"id":"g3","texte":"You will fail unless you work."}],"droite":[{"id":"d0","texte":"Une préférence"},{"id":"d1","texte":"Un souhait irréel"},{"id":"d2","texte":"Tu échoueras si tu ne travailles pas"},{"id":"d3","texte":"Une demande polie"}]},{"enonce":"Tom regrette d’avoir raté le bus. Quelle phrase est correcte ?","aide":"Un regret sur le passé exige le past perfect puis would have + participe.","type":"choix","options":[{"id":"a","texte":"If I hadn’t missed the bus, I would have arrived on time."},{"id":"b","texte":"If I didn’t miss the bus, I would arrive on time."},{"id":"c","texte":"If I hadn’t missed the bus, I would arrive on time."},{"id":"d","texte":"If I wouldn’t have missed the bus, I would have arrived on time."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m18"]},"explication":"**had** et **hadn’t** : après *if*, l’irréel du passé emploie le **past perfect**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Je n’ai pas étudié et j’ai échoué** : le type 3 dit le contraire de ce qui s’est passé."},{"cle":{"type":"trous","trous":[["were"],["unless"]]},"affichage":"were · unless","explication":"**were** (type 2, à toutes les personnes) et **unless** = *if … not* : *unless he works* = *if he doesn’t work*."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*Would like* est poli ; *would rather* dit la préférence ; *wish* + modal dit un souhait irréel ; *unless* = *if … not*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**If I hadn’t missed the bus, I would have arrived on time.** : past perfect après *if*, *would have* + participe passé dans la principale."}]$ex$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un mot au tableau d’affichage","competence":"comprendre-langue","situation":"Une annonce est collée devant le collège. Observe les sujets des phrases anglaises.","documents":[{"id":"annonce","type":"texte","genre":"article","titre":"School notice","blocs":["Hello! There is a problem with the school bus.","It is raining, so the bus is late. Our teacher bought coffee for the driver."],"source":"Annonce écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux sujets « vides »** (there, it).","aide":"Ils n’ont pas de sens propre mais sont obligatoires.","type":"zone","document":"annonce","multiple":true},{"enonce":"Remets en ordre : « Hier, j’ai pris le bus pour aller à l’école. » La phrase commence par Yesterday.","aide":"Ordre de base : sujet, verbe, complément.","type":"ordre","items":[{"id":"a","texte":"took"},{"id":"b","texte":"to school"},{"id":"c","texte":"the bus"},{"id":"d","texte":"Yesterday"},{"id":"e","texte":"I"}]},{"enonce":"Complète la première phrase de l’annonce.","aide":"Il y a un problème = sujet vide.","type":"trous","segments":[0," is a problem with the bus."],"banque":["Have","There","Is","She"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m9"]},"explication":"**There** et **It** : en anglais, le sujet est obligatoire, même quand il ne désigne rien (*There is…*, *It is raining*)."},{"cle":{"type":"ordre","ids":["d","e","a","c","b"]},"explication":"**Yesterday I took the bus to school.** : le repère de temps ouvre la phrase, puis sujet – verbe – complément."},{"cle":{"type":"trous","trous":[["there"]]},"affichage":"There","explication":"**There** : « il y a » se dit *there is* ; le sujet ne peut pas être omis."}]$ex$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à tante Jo","competence":"manier-langue","situation":"Sam raconte à sa tante un dimanche passé à la maison. Observe comment il relie ses idées.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Sam’s letter","blocs":["Dear Aunt Jo,","I stayed home on Sunday because I was ill. It was raining, so I watched films. My brother wanted to play football, but he had a cold. Although it was late, we kept talking until Dad came."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui introduit la **cause** de la présence de Sam à la maison.","aide":"Cherche le « parce que ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Complète pour dire « J’étais malade, donc je suis resté à la maison ».","aide":"Il faut dire la conséquence.","type":"trous","segments":["I was ill, ",0," I stayed home."],"banque":["although","because","but","so"]},{"enonce":"Remets en ordre : « Le bus était en retard parce qu’il pleuvait. » La phrase commence par The bus.","aide":"Because introduit la cause en fin de phrase.","type":"ordre","items":[{"id":"a","texte":"it"},{"id":"b","texte":"was raining"},{"id":"c","texte":"because"},{"id":"d","texte":"The bus"},{"id":"e","texte":"was late"}]},{"enonce":"Associe chaque phrase à son sens.","aide":"Unless = à moins que ; although = bien que.","type":"association","gauche":[{"id":"g0","texte":"I’ll go unless it rains."},{"id":"g1","texte":"Although it was late, he kept working."},{"id":"g2","texte":"I stayed home because I was ill."},{"id":"g3","texte":"It’s small but comfortable."}],"droite":[{"id":"d0","texte":"Je suis resté parce que j’étais malade."},{"id":"d1","texte":"J’irai à moins qu’il pleuve."},{"id":"d2","texte":"Bien qu’il soit tard, il continuait."},{"id":"d3","texte":"C’est petit mais confortable."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**because** introduit la cause ; **so** introduit la conséquence."},{"cle":{"type":"trous","trous":[["so"]]},"affichage":"so","explication":"**so** : *I was ill, so I stayed home* = *I stayed home because I was ill*, dans l’autre sens."},{"cle":{"type":"ordre","ids":["d","e","c","a","b"]},"explication":"**The bus was late because it was raining.** : la proposition principale d’abord, puis la subordonnée de cause introduite par *because* (il pleuvait : *was raining*, une action en cours)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**unless** : condition négative ; **although** : concession ; **because** : cause ; **but** : opposition."}]$ex$::jsonb),
  ('950a43bb-b76f-563d-98a4-dfb135154777'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Un message pour Tara","competence":"argumenter","situation":"Sam organise une rencontre à la gare avec Tara. Lis sa lettre et sa conversation avec elle.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Sam’s letter","blocs":["Hi Tara,","I think the trip will be great. When we arrive, I’ll call you. I’ll wait at the station unless it rains, and please bring the book that I lent you, because I need it.","Sam"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Tara et de Sam","participants":[{"nom":"Tara","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tara","texte":"Thanks, Sam! I’ll bring sandwiches because I know you are always hungry."},{"qui":"Sam","texte":"Perfect. I didn’t see anybody at the station yesterday, so I’ll wait for you there."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction qui introduit une **condition négative** (« à moins que »).","aide":"Elle est suivie de « it rains ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche la conjonction qui introduit la **cause** dans le message de Tara.","aide":"Cherche le « parce que ».","type":"zone","document":"sms","multiple":false},{"enonce":"Range chaque subordonnée selon sa nature.","aide":"When, before = temps ; because, since = cause ; if, unless = condition ; that, who, which = relative.","type":"categories","categories":[{"id":"c0","texte":"Temps"},{"id":"c1","texte":"Cause"},{"id":"c2","texte":"Condition"},{"id":"c3","texte":"Relative"}],"items":[{"id":"i0","texte":"that I lent you"},{"id":"i1","texte":"because I need it"},{"id":"i2","texte":"since I was ill"},{"id":"i3","texte":"unless it rains"},{"id":"i4","texte":"if you come"},{"id":"i5","texte":"before we leave"},{"id":"i6","texte":"When we arrive"}]},{"enonce":"Complète la phrase.","aide":"Après une conjonction de temps, on emploie le présent.","type":"trous","segments":["I’ll call you as soon as I ",0,"."],"banque":["am arriving","arrive","arrived","will arrive"]},{"enonce":"Remets en ordre la phrase de Sam : « Je n’ai vu personne à la gare. » La phrase commence par I.","aide":"Pas de double négation.","type":"ordre","items":[{"id":"a","texte":"see"},{"id":"b","texte":"anybody"},{"id":"c","texte":"I"},{"id":"d","texte":"didn’t"},{"id":"e","texte":"at the station"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Sujet obligatoire, adverbe après l’objet, une seule négation, sujet avant le verbe.","type":"association","gauche":[{"id":"g0","texte":"Is raining."},{"id":"g1","texte":"I like very much football."},{"id":"g2","texte":"I didn’t see nobody."},{"id":"g3","texte":"Yesterday went I to the cinema."}],"droite":[{"id":"d0","texte":"It is raining."},{"id":"d1","texte":"I didn’t see anybody."},{"id":"d2","texte":"I like football very much."},{"id":"d3","texte":"Yesterday I went to the cinema."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**unless** = *if … not* : *I’ll wait unless it rains*."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**because** introduit la subordonnée de cause."},{"cle":{"type":"categories","items":{"i0":"c3","i1":"c1","i2":"c1","i3":"c2","i4":"c2","i5":"c0","i6":"c0"}},"explication":"Le mot introducteur dit la nature de la subordonnée : **when / before** (temps), **because / since** (cause), **if / unless** (condition), **that / who / which** (relative)."},{"cle":{"type":"trous","trous":[["arrive"]]},"affichage":"arrive","explication":"**arrive** : présent après *as soon as* pour parler de l’avenir."},{"cle":{"type":"ordre","ids":["c","d","a","b","e"]},"explication":"**I didn’t see anybody at the station.** : une seule négation (*didn’t*), donc *anybody* et non *nobody*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"En anglais, le sujet est **obligatoire**, l’adverbe ne s’intercale pas entre le verbe et l’objet, la négation est **unique** et l’ordre **sujet – verbe** est fixe."}]$ex$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un coup de main en maths","competence":"comprendre-langue","situation":"Leo a du mal en maths. Il demande de l’aide à Emma par message. Observe les pronoms compléments.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Leo et d’Emma","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Emma","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"Can you help me with maths?"},{"qui":"Emma","texte":"Sure! Tom is good at maths. I’ll ask him to come with us."},{"qui":"Leo","texte":"Great! I’ll text them: Tom and his sister."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre pronoms compléments** des messages.","aide":"Ils suivent un verbe ou une préposition.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète la phrase.","aide":"Tom est complément du verbe asks.","type":"trous","segments":["Tom is good at maths, so Emma asks ",0," for help."],"banque":["himself","his","him","he"]},{"enonce":"Pourquoi écrit-on « with us » et non « with we » ?","aide":"Regarde le mot qui précède le pronom.","type":"choix","options":[{"id":"a","texte":"Parce que we ne peut pas être sujet"},{"id":"b","texte":"Parce que we est un pronom réfléchi"},{"id":"c","texte":"Après une préposition, pronom complément"},{"id":"d","texte":"Parce que with est toujours suivi de us"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m14","m18","m22"]},"explication":"**me, him, us, them** : les pronoms compléments suivent le verbe (*help me, ask him*) ou une préposition (*with us*)."},{"cle":{"type":"trous","trous":[["him"]]},"affichage":"him","explication":"**him** : pronom complément correspondant à *he*, placé après le verbe."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Après une préposition (*with, for, to…*), on emploie le pronom complément** : *with us*, *for them*."}]$ex$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le club d’échecs","competence":"manier-langue","situation":"Le journal du collège présente deux joueurs d’échecs, Anna et Ben. Observe les pronoms réfléchis et « each other ».","documents":[{"id":"club","type":"texte","genre":"article","titre":"Chess club news","blocs":["Anna and Ben love chess. They play each other every Friday.","Last week Anna hurt herself, so Ben wrote the club report by himself. « I did it myself ! » he said."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois pronoms réfléchis** de l’article.","aide":"Ils se terminent par -self.","type":"zone","document":"club","multiple":true},{"enonce":"Associe chaque expression à son sens.","aide":"Each other = l’un l’autre ; by + réfléchi = seul.","type":"association","gauche":[{"id":"g0","texte":"They play each other."},{"id":"g1","texte":"Ben did it by himself."},{"id":"g2","texte":"I did it myself!"},{"id":"g3","texte":"Anna hurt herself."}],"droite":[{"id":"d0","texte":"Il l’a fait tout seul"},{"id":"d1","texte":"J’insiste : c’est moi"},{"id":"d2","texte":"L’action revient sur le sujet"},{"id":"d3","texte":"L’action est réciproque"}]},{"enonce":"Range chaque phrase : réfléchi ou réciproque ?","aide":"Chacun fait-il l’action à l’autre, ou à lui-même ?","type":"categories","categories":[{"id":"c0","texte":"Réfléchi (l’action revient sur le sujet)"},{"id":"c1","texte":"Réciproque (each other)"}],"items":[{"id":"i0","texte":"I taught myself the guitar."},{"id":"i1","texte":"She cut herself."},{"id":"i2","texte":"They kissed each other."},{"id":"i3","texte":"They help each other."}]},{"enonce":"Comment dit-on « Je me lève à sept heures » ?","aide":"Certains verbes pronominaux français n’ont pas de pronom réfléchi en anglais.","type":"choix","options":[{"id":"a","texte":"I get myself up at seven."},{"id":"b","texte":"I me get up at seven."},{"id":"c","texte":"I get up at seven."},{"id":"d","texte":"I raise myself at seven."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m23","m27"]},"explication":"**herself, himself, myself** : les pronoms réfléchis se terminent par -self ou -selves."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*Each other* = réciproque ; *by himself* = tout seul ; *myself* en fin de phrase = insistance ; *hurt herself* = action qui revient sur le sujet."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"**Each other** : deux personnes qui agissent l’une sur l’autre ; **réfléchi** : l’action revient sur celui qui la fait."},{"cle":{"type":"choix","ids":["c"]},"explication":"**I get up at seven.** : *get up* n’est pas pronominal en anglais, comme *wash* ou *feel*."}]$ex$::jsonb),
  ('a75442fe-af8e-5d13-b77d-f97abe6c463d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui a appelé Mia ?","competence":"argumenter","situation":"Jo écrit un mot à Mia. Elle consulte ensuite le tableau des pronoms de son cahier.","documents":[{"id":"mot","type":"texte","genre":"lettre","titre":"Jo’s note","blocs":["Dear Mia,","Between you and me, I am worried. Someone called this morning, but they didn’t leave a message. My brother and I think it was Mr Lee.","Could you ask him? Love, Jo"],"source":"Mot écrit pour l’exercice"},{"id":"table","type":"tableau","titre":"Les pronoms personnels","colonnes":["Sujet","Complément","Adjectif possessif","Pronom possessif","Réfléchi"],"lignes":[["I","me","my","mine","myself"],["you","you","your","yours","yourself"],["he","him","his","his","himself"],["she","her","her","hers","herself"],["it","it","its","—","itself"],["we","us","our","ours","ourselves"],["they","them","their","theirs","themselves"]],"enteteLignes":true,"source":"Tableau récapitulatif"}],"questions":[{"enonce":"Touche le pronom qui désigne **une personne dont le genre est inconnu**.","aide":"Jo ne sait pas qui a téléphoné.","type":"zone","document":"mot","multiple":false},{"enonce":"Complète en t’aidant du tableau.","aide":"Il faut un pronom possessif : colonne « Pronom possessif ».","type":"trous","segments":["These tickets are ",0,", not yours."],"banque":["ourselves","us","our","ours"]},{"enonce":"Remets en ordre : « Mon ami et moi sommes rentrés à la maison. » La phrase commence par My.","aide":"Sujet : I ; on se cite en dernier.","type":"ordre","items":[{"id":"a","texte":"I"},{"id":"b","texte":"My"},{"id":"c","texte":"and"},{"id":"d","texte":"went home"},{"id":"e","texte":"friend"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Après une préposition ou un verbe, le pronom est complément ; l’action réciproque = each other.","type":"association","gauche":[{"id":"g0","texte":"Between you and I"},{"id":"g1","texte":"I him saw."},{"id":"g2","texte":"They kissed themselves."},{"id":"g3","texte":"We met ourselves at six."}],"droite":[{"id":"d0","texte":"I saw him."},{"id":"d1","texte":"They kissed each other."},{"id":"d2","texte":"Between you and me"},{"id":"d3","texte":"We met at six."}]},{"enonce":"D’après le tableau, quel pronom sujet n’a **pas de pronom possessif** ? Écris-le.","aide":"Regarde la colonne « Pronom possessif ».","type":"texte"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**they** s’emploie aussi comme pronom singulier neutre quand on ne connaît pas le genre."},{"cle":{"type":"trous","trous":[["ours"]]},"affichage":"ours","explication":"**ours** : pronom possessif correspondant à *we* (*these tickets are ours*)."},{"cle":{"type":"ordre","ids":["b","e","c","a","d"]},"explication":"**My friend and I went home.** : *I* est sujet et on se nomme en dernier."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Between you and me** (complément après préposition) ; le complément **suit** le verbe ; **each other** pour le réciproque ; pas de réfléchi pour *se retrouver*."},{"cle":{"type":"texte","acceptes":["it"]},"affichage":"it","explication":"**it** : sa case est vide (—) ; on emploie l’adjectif *its*."}]$ex$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La classe de musique","competence":"comprendre-langue","situation":"Dans son journal, une élève présente sa classe de musique. Observe les mots qui relient les phrases.","documents":[{"id":"classe","type":"texte","genre":"article","titre":"My music class","blocs":["In my class there is a girl who plays the drums and a boy who writes songs.","The teacher whose name is Mr Cole loves music. We practise in the hall where we meet on Fridays."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre pronoms relatifs** du texte.","aide":"Ils relient une information à un nom qui les précède.","type":"zone","document":"classe","multiple":true},{"enonce":"Associe chaque antécédent au pronom relatif qui convient.","aide":"Personne, chose, lieu, possession.","type":"association","gauche":[{"id":"g0","texte":"a person"},{"id":"g1","texte":"a thing"},{"id":"g2","texte":"a place"},{"id":"g3","texte":"possession"}],"droite":[{"id":"d0","texte":"where"},{"id":"d1","texte":"who"},{"id":"d2","texte":"which"},{"id":"d3","texte":"whose"}]},{"enonce":"Complète la phrase.","aide":"L’antécédent est une personne.","type":"trous","segments":["I have a friend ",0," speaks Chinese."],"banque":["where","whose","which","who"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m14","m19","m31"]},"explication":"**who, who, whose, where** : *who* pour une personne, *whose* pour la possession, *where* pour un lieu."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**who** : personne ; **which** : chose ; **where** : lieu ; **whose** : possession."},{"cle":{"type":"trous","trous":[["who"]]},"affichage":"who","explication":"**who** : l’antécédent *a friend* est une personne."}]$ex$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre de Londres","competence":"manier-langue","situation":"Ana écrit à sa mère. Observe où se placent les virgules autour des relatives.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Ana’s letter","blocs":["Dear Mum,","My brother, who lives in London, is a teacher. The book that I bought is about space. The girl whose father is a doctor is in my class.","Love, Ana"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le pronom qui introduit la **relative explicative** (entre virgules).","aide":"Cherche l’information entourée de virgules.","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque phrase : relative déterminative ou explicative ?","aide":"Peut-on supprimer la relative sans changer le sens ?","type":"categories","categories":[{"id":"c0","texte":"Déterminative (indispensable)"},{"id":"c1","texte":"Explicative (entre virgules)"}],"items":[{"id":"i0","texte":"London, which is the capital of the UK, is huge."},{"id":"i1","texte":"The film that I watched was great."},{"id":"i2","texte":"The man who lives next door is a doctor."},{"id":"i3","texte":"The girl who sits next to me is my cousin."},{"id":"i4","texte":"My sister, who lives in Rome, is a nurse."}]},{"enonce":"Dans quelle phrase le pronom relatif peut-il être omis ?","aide":"Le pronom peut sauter quand il est complément d’une relative déterminative.","type":"choix","options":[{"id":"a","texte":"My brother, who lives in Rome, is a teacher."},{"id":"b","texte":"The film that I watched was great."},{"id":"c","texte":"The girl whose father is a doctor is my friend."},{"id":"d","texte":"The man who called me was rude."}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le premier est entre virgules ; le second marque la possession.","type":"trous","segments":["My sister, ",0," lives in Rome, is a nurse, and the girl ",1," father is a doctor is my friend."],"banque":["whose","which","that","who"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**who** : la relative *who lives in London* est entre virgules, elle ajoute une information non indispensable."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"La **déterminative** est indispensable, sans virgule ; l’**explicative** ajoute une information, entre virgules."},{"cle":{"type":"choix","ids":["b"]},"explication":"**The film (that) I watched was great.** : *that* est complément ; il peut être omis. Un pronom sujet ne s’omet jamais."},{"cle":{"type":"trous","trous":[["who"],["whose"]]},"affichage":"who · whose","explication":"**who** (relative explicative : *that* est impossible) et **whose** (possession)."}]$ex$::jsonb),
  ('5e047d4a-274b-5df5-a753-eeb28d43c615'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le match dont tout le monde parle","competence":"argumenter","situation":"Une élève parle de son livre préféré, puis deux amis commentent un match de football.","documents":[{"id":"livre","type":"texte","genre":"article","titre":"My favourite book","blocs":["This is the book that I read last summer. It was written by an author who lives in Wales, a country where it rains a lot."],"source":"Texte écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Max et d’Ana","participants":[{"nom":"Max","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Max","texte":"Do you know what happened at the match?"},{"qui":"Ana","texte":"Yes! The player who scored the goal is my cousin."},{"qui":"Max","texte":"Is he the boy whose picture is in the newspaper?"},{"qui":"Ana","texte":"Yes, he’s the one everybody talks about."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif qui pourrait être **omis** sans changer le sens.","aide":"Il est complément dans une relative déterminative.","type":"zone","document":"livre","multiple":false},{"enonce":"Remets en ordre : « Tout ce qu’il a dit était vrai. » La phrase commence par Everything.","aide":"Après everything, on emploie that.","type":"ordre","items":[{"id":"a","texte":"he"},{"id":"b","texte":"was"},{"id":"c","texte":"said"},{"id":"d","texte":"that"},{"id":"e","texte":"true"},{"id":"f","texte":"Everything"}]},{"enonce":"Quelle phrase relie correctement « This is the house. I grew up there. » ?","aide":"Un lieu appelle where.","type":"choix","options":[{"id":"a","texte":"This is the house which I grew up there."},{"id":"b","texte":"This is the house whose I grew up."},{"id":"c","texte":"This is the house who I grew up."},{"id":"d","texte":"This is the house where I grew up."}],"multiple":false},{"enonce":"Touche le pronom relatif qui exprime la **possession** dans le message de Max.","aide":"Cherche « dont la photo ».","type":"zone","document":"sms","multiple":false},{"enonce":"Associe chaque erreur à sa correction.","aide":"Personne, possession, pas de pronom en double, that impossible entre virgules.","type":"association","gauche":[{"id":"g0","texte":"the man which lives here"},{"id":"g1","texte":"the girl who her father is a doctor"},{"id":"g2","texte":"the book that I read it"},{"id":"g3","texte":"My sister, that lives in Rome, …"}],"droite":[{"id":"d0","texte":"the girl whose father is a doctor"},{"id":"d1","texte":"the man who lives here"},{"id":"d2","texte":"the book that I read"},{"id":"d3","texte":"My sister, who lives in Rome, …"}]},{"enonce":"Complète la phrase.","aide":"Il n’y a pas d’antécédent.","type":"trous","segments":["Tell me ",0," happened at the match."],"banque":["what","who","that","which"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**that** : *the book (that) I read* — il est complément et peut sauter. *Who* est sujet et *where* introduit un lieu."},{"cle":{"type":"ordre","ids":["f","d","a","c","b","e"]},"explication":"**Everything that he said was true.** : *everything* est suivi de *that*, jamais de « what »."},{"cle":{"type":"choix","ids":["d"]},"explication":"**This is the house where I grew up.** : *where* remplace *there*."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**whose** : *the boy whose picture…* = le garçon dont la photo…"},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"*Who* pour une personne ; *whose* pour la possession ; pas de pronom en double ; *that* est impossible dans une relative explicative."},{"cle":{"type":"trous","trous":[["what"]]},"affichage":"what","explication":"**what** : « ce qui » se dit *what*, sans antécédent."}]$ex$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Au club de théâtre","competence":"comprendre-langue","situation":"Mia invite Tom au club de théâtre. Lis leurs questions et repère les auxiliaires.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Mia et de Tom","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Hi Tom! Do you like acting?"},{"qui":"Tom","texte":"I love it! Where do you rehearse?"},{"qui":"Mia","texte":"In the hall. We start at four."},{"qui":"Tom","texte":"And when does the club finish?"},{"qui":"Mia","texte":"At five!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois auxiliaires** (do, do, does) qui ouvrent les questions.","aide":"Ils se placent devant le sujet.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque mot interrogatif à ce qu’il demande.","aide":"Lieu, moment, cause, personne.","type":"association","gauche":[{"id":"g0","texte":"Where"},{"id":"g1","texte":"When"},{"id":"g2","texte":"Why"},{"id":"g3","texte":"Who"}],"droite":[{"id":"d0","texte":"Le moment"},{"id":"d1","texte":"La personne"},{"id":"d2","texte":"Le lieu"},{"id":"d3","texte":"La cause"}]},{"enonce":"Remets en ordre la question de Tom : « Quand le club finit-il ? » La phrase commence par When.","aide":"Mot interrogatif, auxiliaire, sujet, verbe.","type":"ordre","items":[{"id":"a","texte":"club"},{"id":"b","texte":"finish"},{"id":"c","texte":"does"},{"id":"d","texte":"When"},{"id":"e","texte":"the"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m10","m22"]},"explication":"**Do, do, does** : avec un temps simple, on introduit *do / does / did* devant le sujet."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**where** : où ; **when** : quand ; **why** : pourquoi ; **who** : qui."},{"cle":{"type":"ordre","ids":["d","c","e","a","b"]},"explication":"**When does the club finish ?** : mot interrogatif + auxiliaire + sujet + verbe à la base verbale."}]$ex$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’interview du nouveau","competence":"manier-langue","situation":"Un journaliste du collège interroge Jo, le nouvel élève. Observe les questions en « how ».","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Interview de Jo","participants":[{"nom":"Reporter","emoji":"🎤","cote":"gauche"},{"nom":"Jo","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Reporter","texte":"How old are you, Jo?"},{"qui":"Jo","texte":"I’m twelve."},{"qui":"Reporter","texte":"How far is your house from school?"},{"qui":"Jo","texte":"Two kilometres."},{"qui":"Reporter","texte":"How often do you come by bike?"},{"qui":"Jo","texte":"Every day."},{"qui":"Reporter","texte":"And how long have you lived here?"},{"qui":"Jo","texte":"For two years."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui demande une **fréquence**.","aide":"Jo répond « Every day ».","type":"zone","document":"sms","multiple":false},{"enonce":"Associe chaque question à ce qu’elle demande.","aide":"Âge, distance, fréquence, durée.","type":"association","gauche":[{"id":"g0","texte":"How old are you?"},{"id":"g1","texte":"How far is your house?"},{"id":"g2","texte":"How often do you come by bike?"},{"id":"g3","texte":"How long have you lived here?"}],"droite":[{"id":"d0","texte":"La distance"},{"id":"d1","texte":"La fréquence"},{"id":"d2","texte":"La durée"},{"id":"d3","texte":"L’âge"}]},{"enonce":"Complète la dernière question du journaliste.","aide":"Jo répond « For two years ».","type":"trous","segments":["How ",0," have you lived here?"],"banque":["old","often","long","far"]},{"enonce":"Remets en ordre : « À quelle distance est ta maison ? » La phrase commence par How.","aide":"Avec be, l’auxiliaire passe avant le sujet.","type":"ordre","items":[{"id":"a","texte":"your"},{"id":"b","texte":"far"},{"id":"c","texte":"house"},{"id":"d","texte":"How"},{"id":"e","texte":"is"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"**often** : *how often* demande la fréquence."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**how old** : âge ; **how far** : distance ; **how often** : fréquence ; **how long** : durée."},{"cle":{"type":"trous","trous":[["long"]]},"affichage":"long","explication":"**long** : *how long* interroge sur une durée."},{"cle":{"type":"ordre","ids":["d","b","e","a","c"]},"explication":"**How far is your house ?** : *how far* + *is* + sujet."}]$ex$::jsonb),
  ('1b264862-f8ce-5efb-8d05-d96a023aab9a'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Qui a cassé la fenêtre ?","competence":"argumenter","situation":"Une vitre du gymnase est brisée. Mr Hall interroge Tom, puis Jade lui envoie un petit mot.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Mr Hall et de Tom","participants":[{"nom":"Mr Hall","emoji":"👨","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mr Hall","texte":"Who broke the window?"},{"qui":"Tom","texte":"I don’t know. I was in the gym."},{"qui":"Mr Hall","texte":"Who did you see near the gym?"},{"qui":"Tom","texte":"I saw Jade and her brother."}],"source":"Messages écrits pour l’exercice"},{"id":"mot","type":"texte","genre":"lettre","titre":"Jade’s note","blocs":["Dear Mr Hall,","Do you know what time the match starts? Could you tell me where the gym is? Thank you, Jade"],"source":"Mot écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **verbe** de la question où **who est sujet** (sans do).","aide":"Dans cette question, le verbe est au prétérit.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le mot qui montre que **who est complément** dans la deuxième question.","aide":"Cherche l’auxiliaire.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète d’après le mot de Jade.","aide":"La question directe prend un auxiliaire ; la question indirecte garde l’ordre de l’affirmative.","type":"trous","segments":["What time ",0," the match start? Could you tell me what time it ",1,"?"],"banque":["do","starts","start","does"]},{"enonce":"Remets en ordre la question indirecte : « Sais-tu où elle habite ? » La phrase commence par Do.","aide":"Après where, l’ordre redevient sujet puis verbe.","type":"ordre","items":[{"id":"a","texte":"you"},{"id":"b","texte":"she"},{"id":"c","texte":"where"},{"id":"d","texte":"lives"},{"id":"e","texte":"Do"},{"id":"f","texte":"know"}]},{"enonce":"Range chaque question : who sujet ou who complément ?","aide":"Si who fait l’action, il n’y a pas d’auxiliaire.","type":"categories","categories":[{"id":"c0","texte":"Who sujet (sans do)"},{"id":"c1","texte":"Who complément (avec do)"}],"items":[{"id":"i0","texte":"Who wrote this letter?"},{"id":"i1","texte":"Who called you?"},{"id":"i2","texte":"Who broke the window?"},{"id":"i3","texte":"Who are you talking to?"},{"id":"i4","texte":"Who did you call?"},{"id":"i5","texte":"Who did she meet?"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Auxiliaire, base verbale, be pour l’âge, who sujet.","type":"association","gauche":[{"id":"g0","texte":"Where you live?"},{"id":"g1","texte":"What did she said?"},{"id":"g2","texte":"How old have you?"},{"id":"g3","texte":"Who did call you?"}],"droite":[{"id":"d0","texte":"What did she say?"},{"id":"d1","texte":"How old are you?"},{"id":"d2","texte":"Who called you?"},{"id":"d3","texte":"Where do you live?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**broke** : quand *who* est sujet, il n’y a pas de *did* et l’ordre reste celui de l’affirmative (*Who broke the window ?*)."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**did** : quand *who* est complément, on a l’ordre *who + auxiliaire + sujet + verbe*."},{"cle":{"type":"trous","trous":[["does"],["starts"]]},"affichage":"does · starts","explication":"**does** dans la question directe ; **starts** dans la question indirecte (ordre de l’affirmative, sans auxiliaire)."},{"cle":{"type":"ordre","ids":["e","a","f","c","b","d"]},"explication":"**Do you know where she lives ?** : dans la question enchâssée, on garde l’ordre sujet – verbe."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c1"}},"explication":"**Who sujet** : pas de *do*, ordre de l’affirmative ; **who complément** : auxiliaire + sujet + verbe."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Il faut l’**auxiliaire** ; après *did* on revient à la **base verbale** ; l’âge se dit avec **be** ; avec *who* sujet, pas de *did*."}]$ex$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une sortie au musée par SMS","competence":"comprendre-langue","situation":"Maya et Ben s’écrivent la veille d’une sortie scolaire. Observe les petites questions qu’ils ajoutent en fin de phrase.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Maya et de Ben","participants":[{"nom":"Maya","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"Our trip to the museum is on Friday, isn’t it?"},{"qui":"Ben","texte":"Yes! We meet at the gate at eight. You have your ticket, haven’t you?"},{"qui":"Maya","texte":"Yes, I do. Oh no, we aren’t late, are we?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le **question tag** qui termine le premier message de Maya.","aide":"C’est la petite question de deux mots juste avant le point d’interrogation.","type":"zone","document":"sms","multiple":true},{"enonce":"Dans le message de Ben, pourquoi le tag est-il « haven’t you ? »","aide":"Regarde si la phrase de départ contient un *not*.","type":"choix","options":[{"id":"a","texte":"Parce que le tag doit toujours être « haven’t »"},{"id":"b","texte":"Parce que Maya a posé une question avant"},{"id":"c","texte":"Parce que la phrase « You have your ticket » est négative"},{"id":"d","texte":"Parce que la phrase « You have your ticket » est affirmative"}],"multiple":false},{"enonce":"Ben ajoute : « We meet at the gate at eight, ___ we? » Complète le tag.","aide":"Il n’y a pas d’auxiliaire visible : il faut do, does ou did.","type":"trous","segments":["We meet at the gate at eight, ",0," we?"],"banque":["won’t","aren’t","don’t","haven’t"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m9"]},"explication":"**isn’t it** : la phrase « The trip is on Friday » est affirmative, le tag est négatif et reprend l’auxiliaire *is*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Phrase affirmative, tag négatif** : *You have… haven’t you?* L’auxiliaire *have* est repris."},{"cle":{"type":"trous","trous":[["don t"]]},"affichage":"don’t","explication":"**don’t** : présent simple sans auxiliaire, on emploie *do* ; phrase affirmative, donc tag négatif."}]$ex$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les règles du club de natation","competence":"manier-langue","situation":"Léa vient de s’inscrire au club de natation. Le coach affiche les règles et vérifie qu’elle a tout compris.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Swimming club — Saturday, 10 a.m.","emoji":"🏊","lignes":[{"texte":"Everyone brings a towel.","id":"z1"},{"texte":"Lock your bag in the locker.","id":"z2"},{"texte":"There are twelve places left in the group.","id":"z3"},{"texte":"Lea is our new swimmer.","id":"z4"}],"pied":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui est un **ordre** : on lui ajoute le tag « will you ? ».","aide":"Un ordre n’a pas de sujet exprimé.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète le tag de la règle sur les places.","aide":"Avec *there is / there are*, on reprend le verbe *be* et le mot *there*.","type":"trous","segments":["There are twelve places left in the group, ",0," there?"],"banque":["isn’t","aren’t","are","don’t"]},{"enonce":"Associe chaque phrase à son question tag.","aide":"Cherche l’auxiliaire, puis inverse la polarité. Deux cas sont à connaître par cœur.","type":"association","gauche":[{"id":"g0","texte":"Lea is our new swimmer,"},{"id":"g1","texte":"You can dive,"},{"id":"g2","texte":"They didn’t come,"},{"id":"g3","texte":"Let’s start,"},{"id":"g4","texte":"I am next,"}],"droite":[{"id":"d0","texte":"isn’t she?"},{"id":"d1","texte":"can’t you?"},{"id":"d2","texte":"shall we?"},{"id":"d3","texte":"did they?"},{"id":"d4","texte":"aren’t I?"}]},{"enonce":"Range ces phrases selon le tag qu’elles réclament.","aide":"*Never* et *nothing* rendent la phrase négative.","type":"categories","categories":[{"id":"c0","texte":"Tag négatif (phrase affirmative)"},{"id":"c1","texte":"Tag affirmatif (phrase négative)"}],"items":[{"id":"i0","texte":"They never wear caps."},{"id":"i1","texte":"Tom doesn’t like cold water."},{"id":"i2","texte":"Lea swims well."},{"id":"i3","texte":"You have a locker."},{"id":"i4","texte":"Nothing happened."},{"id":"i5","texte":"We can start."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Lock your bag in the locker** est un impératif : *Lock your bag in the locker, will you?*"},{"cle":{"type":"trous","trous":[["aren t"]]},"affichage":"aren’t","explication":"**aren’t** : *There are…, aren’t there?* Phrase affirmative, tag négatif, *there* est repris."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3","g4":"d4"}},"explication":"On reprend l’auxiliaire, on inverse la polarité. Cas particuliers : *Let’s… shall we?* et *I am… aren’t I?*"},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Phrase affirmative → tag négatif. Phrase négative, y compris avec *never* ou *nothing* → tag affirmatif."}]$ex$::jsonb),
  ('932d2c69-b0a2-523b-af62-eafb0fdd8913'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le courriel de Jo à corriger","competence":"analyser-document","situation":"Jo écrit à sa cousine Lou, mais deux de ses tags sont faux. Lou lui répond ensuite par SMS à une autre question.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Un courriel de Jo","blocs":["Hi Lou,","Your sister works at the new café, isn’t it? She makes great pancakes, doesn’t she? They can’t open on Sundays, can’t they? Let me know, will you?","Jo"],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Jo et Lou, le soir","participants":[{"nom":"Jo","emoji":"👧","cote":"gauche"},{"nom":"Lou","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jo","texte":"You aren’t working tonight, are you?"},{"qui":"Lou","texte":"… I’m free until midnight!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux tags faux** dans le courriel de Jo.","aide":"Pour chaque tag, vérifie l’auxiliaire, la polarité et le pronom.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige le premier tag en complétant avec deux mots.","aide":"Présent simple, 3e personne du singulier, sujet féminin.","type":"trous","segments":["Your sister works at the new café, ",0," ",1,"?"],"banque":["isn’t","it","don’t","doesn’t","does","she"]},{"enonce":"Remets en ordre : « Le café ne peut pas ouvrir, n’est-ce pas ? » Commence par The.","aide":"Phrase négative d’abord, puis le tag affirmatif.","type":"ordre","items":[{"id":"a","texte":"it"},{"id":"b","texte":"can"},{"id":"c","texte":"café"},{"id":"d","texte":"The"},{"id":"e","texte":"can’t"},{"id":"f","texte":"open"}]},{"enonce":"Quelle réponse de Lou veut dire « Non, je ne travaille pas ce soir » ?","aide":"On répond à ce qui est vrai, pas au tag. Lou est libre.","type":"choix","options":[{"id":"a","texte":"No, I am."},{"id":"b","texte":"Yes, I am."},{"id":"c","texte":"No, I’m not."},{"id":"d","texte":"Yes, I’m not."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10","m22","m23"]},"explication":"**isn’t it** devrait être *doesn’t she* (présent simple, sujet *your sister*) ; **can’t they** devrait être *can they* (phrase négative, tag affirmatif)."},{"cle":{"type":"trous","trous":[["doesn t"],["she"]]},"affichage":"doesn’t · she","explication":"**doesn’t she** : *do* à la 3e personne, polarité inversée, *your sister* devient *she*."},{"cle":{"type":"ordre","ids":["d","c","e","f","b","a"]},"explication":"**The café can’t open, can it?** Phrase négative suivie d’un tag affirmatif ; *the café* est repris par *it*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**No, I’m not.** On répond selon la réalité : Lou ne travaille pas, donc *No* + forme négative."}]$ex$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Cornouailles","competence":"comprendre-langue","situation":"Ella passe la semaine au bord de la mer et écrit à sa grand-mère. Elle exclame tout ce qu’elle découvre.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Postcard from Cornwall","blocs":["Dear Gran,","What a beautiful beach! How warm the water is! What lovely weather! We are having such a good time.","Love, Ella"],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les mots qui introduisent une exclamation devant un **nom**.","aide":"Après ce mot viennent *a beautiful beach* et *lovely weather* : des noms.","type":"zone","document":"carte","multiple":true},{"enonce":"Pourquoi n’y a-t-il pas de *a* dans « What lovely weather! » ?","aide":"On ne dit jamais *a weather*.","type":"choix","options":[{"id":"a","texte":"Parce que weather est indénombrable"},{"id":"b","texte":"Parce que lovely remplace l’article"},{"id":"c","texte":"Parce que what suffit au singulier"},{"id":"d","texte":"Parce que weather est un pluriel"}],"multiple":false},{"enonce":"Complète la dernière phrase de la carte.","aide":"Il y a un article *a* et un nom après le blanc.","type":"trous","segments":["We are having ",0," a good time."],"banque":["how","so","what","such"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m11"]},"explication":"**What** introduit une exclamation devant un nom ; **How** se met devant un adjectif ou un adverbe."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Weather est indénombrable** : pas d’article *a / an* après *what*."},{"cle":{"type":"trous","trous":[["such"]]},"affichage":"such","explication":"**such a** + adjectif + nom singulier : *such a good time*. *So* se met devant un adjectif seul."}]$ex$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des billets pour le concert du collège","competence":"manier-langue","situation":"Mia a gagné deux places pour le concert, mais son père hésite. Leo réagit à chaque nouvelle.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Mia et Leo","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Guess what? I won two tickets for the school concert!"},{"qui":"Leo","texte":"No way! What a surprise! How lucky you are!"},{"qui":"Mia","texte":"But my dad says no. The show is on a school night."},{"qui":"Leo","texte":"What a pity! How come?"},{"qui":"Mia","texte":"He says it starts so late!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la question de Leo qui signifie « **Comment ça se fait ?** »","aide":"C’est une expression toute faite, pas une exclamation.","type":"zone","document":"sms","multiple":true},{"enonce":"Remets en ordre l’exclamation de Leo : « Comme tu as de la chance ! » Commence par How.","aide":"Après l’adjectif, on garde l’ordre sujet puis verbe.","type":"ordre","items":[{"id":"a","texte":"How"},{"id":"b","texte":"are"},{"id":"c","texte":"you"},{"id":"d","texte":"lucky"}]},{"enonce":"Associe chaque exclamation à son sens.","aide":"Relis les messages : Leo en emploie plusieurs.","type":"association","gauche":[{"id":"g0","texte":"What a pity!"},{"id":"g1","texte":"How come?"},{"id":"g2","texte":"Well done!"},{"id":"g3","texte":"No way!"}],"droite":[{"id":"d0","texte":"Quel dommage !"},{"id":"d1","texte":"Pas question !"},{"id":"d2","texte":"Comment ça se fait ?"},{"id":"d3","texte":"Bravo !"}]},{"enonce":"Leo veut dire que le concert est un événement très tardif, avec un nom. Quelle phrase est correcte ?","aide":"Devant un nom singulier, il faut *such a*.","type":"choix","options":[{"id":"a","texte":"It is so a late show!"},{"id":"b","texte":"It is what a late show!"},{"id":"c","texte":"It is so late show!"},{"id":"d","texte":"It is such a late show!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34","m35"]},"explication":"**How come?** veut dire « Comment ça se fait ? » ; ce n’est pas une exclamation."},{"cle":{"type":"ordre","ids":["a","d","c","b"]},"explication":"**How lucky you are!** Pas d’inversion : le sujet reste devant le verbe."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Ces expressions toutes faites sont à connaître par cœur, sans les traduire mot à mot."},{"cle":{"type":"choix","ids":["d"]},"explication":"**such a** + adjectif + nom singulier. *So* se met devant un adjectif sans nom."}]$ex$::jsonb),
  ('bd43e615-93e1-54e7-ba98-9eee2c7d1881'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le blog du voyage à Édimbourg","competence":"analyser-document","situation":"Une classe revient d’Écosse et publie un blog. Deux exclamations sont fautives ; une fiche rappelle quels noms prennent un article.","documents":[{"id":"blog","type":"texte","genre":"article","titre":"School blog — Edinburgh","blocs":["The castle is so a big building that we spent the whole morning there.","What a terrible weather we had in the afternoon! How cold it was!"],"source":"Article écrit pour l’exercice"},{"id":"noms","type":"tableau","titre":"Quelques noms utiles","colonnes":["Nom","Dénombrable au singulier ?"],"lignes":[["castle","oui"],["view","oui"],["weather","non"],["luck","non"],["flowers","pluriel"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot fautif de la **première phrase** du blog.","aide":"Il y a un nom singulier avec *a* ; l’adjectif seul n’est pas là.","type":"zone","document":"blog","multiple":false},{"enonce":"Corrige la première phrase.","aide":"Il y a un nom derrière.","type":"trous","segments":["The castle is ",0," a big building that we spent the whole morning there."],"banque":["what","such","how","so"]},{"enonce":"La deuxième phrase du blog contient aussi une faute (« What a terrible weather »). Range ces noms selon l’exclamation qu’ils permettent, en t’aidant de la fiche.","aide":"Regarde la colonne « dénombrable au singulier ». *Surprise* se compte.","type":"categories","categories":[{"id":"c0","texte":"What a / an + nom"},{"id":"c1","texte":"What + nom (sans article)"}],"items":[{"id":"i0","texte":"view"},{"id":"i1","texte":"flowers"},{"id":"i2","texte":"castle"},{"id":"i3","texte":"weather"},{"id":"i4","texte":"luck"},{"id":"i5","texte":"surprise"}]},{"enonce":"Remets en ordre : « Il faisait si froid que nous sommes partis. » Commence par It.","aide":"*So* + adjectif + *that* + conséquence.","type":"ordre","items":[{"id":"a","texte":"that"},{"id":"b","texte":"It"},{"id":"c","texte":"cold"},{"id":"d","texte":"we"},{"id":"e","texte":"so"},{"id":"f","texte":"left"},{"id":"g","texte":"was"}]},{"enonce":"Quelle exclamation correspond à « The museum is very interesting » ?","aide":"Pas d’inversion dans une exclamation.","type":"choix","options":[{"id":"a","texte":"How the museum is interesting!"},{"id":"b","texte":"How interesting the museum is!"},{"id":"c","texte":"How interesting is the museum!"},{"id":"d","texte":"What interesting the museum is!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**so** est faux ici : devant *a big building* (adjectif + nom), il faut **such a**."},{"cle":{"type":"trous","trous":[["such"]]},"affichage":"such","explication":"**such a** big building : *such a* + adjectif + nom singulier."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Nom singulier dénombrable : *What a view!* Nom indénombrable ou pluriel : *What weather!*, *What luck!*, *What flowers!*"},{"cle":{"type":"ordre","ids":["b","g","e","c","a","d","f"]},"explication":"**It was so cold that we left.** *So* + adjectif, puis *that* introduit la conséquence."},{"cle":{"type":"choix","ids":["b"]},"explication":"**How interesting the museum is!** *How* + adjectif + sujet + verbe."}]$ex$::jsonb),
  ('bd1ddb34-e55d-5d2a-a85f-c0615a300c30'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les nouvelles du collège","competence":"comprendre-langue","situation":"Le journal du collège raconte l’histoire de l’établissement et les événements récents.","documents":[{"id":"news","type":"texte","genre":"article","titre":"School news","blocs":["Our school was built in 1965. Every year, the garden is cleaned by pupils. This morning, a prize was given to Zara."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le verbe passif de la première phrase.","aide":"Le passif se forme avec *be* puis le participe passé.","type":"zone","document":"news","multiple":true},{"enonce":"Dans « the garden is cleaned by pupils », qui fait l’action ?","aide":"Le mot qui suit *by* est l’auteur.","type":"choix","options":[{"id":"a","texte":"The pupils"},{"id":"b","texte":"Zara"},{"id":"c","texte":"The garden"},{"id":"d","texte":"The school"}],"multiple":false},{"enonce":"Complète avec la bonne forme de *be*.","aide":"Le texte dit « this morning » : l’action est terminée.","type":"trous","segments":["A prize ",0," given to Zara."],"banque":["were","was","is","has"]}]}$ex$::jsonb,
