  ('bd1ddb34-e55d-5d2a-a85f-c0615a300c30'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le chantier du musée","competence":"manier-langue","situation":"Un musée affiche l’histoire de ses travaux. Tu dois en faire des phrases à la voix passive.","documents":[{"id":"histoire","type":"tableau","titre":"Les grandes dates du musée","colonnes":["Date","Qui","Action"],"lignes":[["1890","a banker","founded the museum"],["2005","the city","repaired the roof"],["Today","workers","are building a new wing"],["Next year","the mayor","will open the new wing"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Mets au passif le deuxième événement, sans l’auteur : « Le toit a été réparé en 2005. » Commence par The.","aide":"Le complément devient sujet, puis *be* au prétérit et le participe passé.","type":"ordre","items":[{"id":"a","texte":"2005"},{"id":"b","texte":"was"},{"id":"c","texte":"repaired"},{"id":"d","texte":"roof"},{"id":"e","texte":"in"},{"id":"f","texte":"The"}]},{"enonce":"Complète le passif de la phrase en cours.","aide":"Présent en BE + -ING au passif.","type":"trous","segments":["Today, a new wing ",0," ",1," built by workers."],"banque":["been","was","being","be","are","is"]},{"enonce":"Quelle phrase est le passif de « The mayor will open the new wing next year » ?","aide":"Modal *will* + *be* + participe passé.","type":"choix","options":[{"id":"a","texte":"The new wing will be opened by the mayor next year."},{"id":"b","texte":"The new wing will be open by the mayor next year."},{"id":"c","texte":"The new wing is opened by the mayor next year."},{"id":"d","texte":"The new wing will opened by the mayor next year."}],"multiple":false},{"enonce":"Associe chaque phrase active à sa phrase passive.","aide":"Garde le même temps pour *be*.","type":"association","gauche":[{"id":"g0","texte":"They built the bridge in 1990."},{"id":"g1","texte":"They are repairing the road."},{"id":"g2","texte":"They have sold the tickets."},{"id":"g3","texte":"They can fix it."}],"droite":[{"id":"d0","texte":"The road is being repaired."},{"id":"d1","texte":"The tickets have been sold."},{"id":"d2","texte":"The bridge was built in 1990."},{"id":"d3","texte":"It can be fixed."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["f","d","b","c","e","a"]},"explication":"**The roof was repaired in 2005.** L’objet *the roof* devient sujet."},{"cle":{"type":"trous","trous":[["is"],["being"]]},"affichage":"is · being","explication":"**is being built** : *be* au présent + *being* + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**will be opened** : futur passif = *will be* + participe passé."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"Le passif garde le temps du verbe actif : *was built*, *is being repaired*, *have been sold*, *can be fixed*."}]$ex$::jsonb),
