   $ex${"titre":"La tempête sur le village","competence":"analyser-document","situation":"Un journal local raconte une tempête et la préfecture publie un avis. Tu cherches les erreurs et tu passes de l’actif au passif.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"Storm hits village","blocs":["A storm hit the village last night. Three windows broken by the wind, and a tree was blown down. Nobody was hurt. The road has been closed."],"source":"Article écrit pour l’exercice"},{"id":"avis","type":"fiche","modele":"panneau","entete":"Storm warning — Saturday","emoji":"⚠️","lignes":[{"texte":"Roads will be closed from 9 p.m.","id":"z1"},{"texte":"A shelter is being prepared at the school.","id":"z2"},{"texte":"Cars must be moved to the car park.","id":"z3"}],"pied":"Avis écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **mot mal formé** : il manque quelque chose pour que la phrase soit à la voix passive.","aide":"Il manque *be*, mais ce n’est pas le mot qui est faux.","type":"zone","document":"journal","multiple":false},{"enonce":"Corrige la phrase.","aide":"Sujet pluriel, prétérit.","type":"trous","segments":["Three windows ",0," ",1," by the wind."],"banque":["broken","been","was","broke","breaking","were"]},{"enonce":"Quelle phrase active correspond à « The road has been closed » ?","aide":"Garde le même temps.","type":"choix","options":[{"id":"a","texte":"Someone has closed the road."},{"id":"b","texte":"Someone closed the road."},{"id":"c","texte":"Someone was closing the road."},{"id":"d","texte":"Someone will close the road."}],"multiple":false},{"enonce":"Touche la ligne de l’avis dont le verbe est un passif en **BE + -ING**.","aide":"Cherche *being*.","type":"zone","document":"avis","multiple":false},{"enonce":"Mets au double passif le plus courant : « Quelqu’un m’a offert un vélo. » Commence par I.","aide":"Le premier complément, *me*, devient sujet.","type":"ordre","items":[{"id":"a","texte":"bike"},{"id":"b","texte":"I"},{"id":"c","texte":"a"},{"id":"d","texte":"given"},{"id":"e","texte":"was"}]},{"enonce":"Associe chaque erreur à sa correction.","aide":"Pense à *be*, au participe passé et à *by*.","type":"association","gauche":[{"id":"g0","texte":"I am born in 2011"},{"id":"g1","texte":"The house was build in 1900"},{"id":"g2","texte":"The letter was written of her"},{"id":"g3","texte":"The window broken"}],"droite":[{"id":"d0","texte":"The window was broken"},{"id":"d1","texte":"I was born in 2011"},{"id":"d2","texte":"The letter was written by her"},{"id":"d3","texte":"The house was built in 1900"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**broken** est seul : il faut *were broken*. Le participe passé ne suffit pas."},{"cle":{"type":"trous","trous":[["were"],["broken"]]},"affichage":"were · broken","explication":"**were broken** : *be* au prétérit pluriel + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Someone has closed the road.** *has been closed* est le passif du present perfect."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**A shelter is being prepared** : présent en BE + -ING au passif."},{"cle":{"type":"ordre","ids":["b","e","d","c","a"]},"explication":"**I was given a bike.** Avec *give*, le passif le plus courant a pour sujet la personne."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"Il faut *be* au bon temps, un participe passé correct et *by* pour l’auteur."}]$ex$::jsonb),
  ('ff6ca0a5-a3dd-5cb1-836a-ad0b3941a5f6'::uuid, 1, 1, 5, 20, 3,
