   $ex${"titre":"Rome ou Lisbonne pour les vacances ?","competence":"manier-langue","situation":"Ava et Jack hésitent entre deux destinations et comparent tout par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Ava et Jack","participants":[{"nom":"Ava","emoji":"👧","cote":"gauche"},{"nom":"Jack","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ava","texte":"Look! The hotel in Rome is more expensive than the hotel in Lisbon."},{"qui":"Jack","texte":"But the weather is better in Lisbon, and the beach is nicer."},{"qui":"Ava","texte":"The flight to Rome is as long as the flight to Lisbon, though."},{"qui":"Jack","texte":"OK, let’s book Lisbon!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux comparatifs** de Jack (ni *more*, ni *as … as*).","aide":"Cherche des adjectifs qui se terminent par -er.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète la phrase d’Ava sur les vols.","aide":"Les deux vols durent autant.","type":"trous","segments":["The flight to Rome is as long ",0," the flight to Lisbon."],"banque":["than","like","that","as"]},{"enonce":"Range ces adjectifs selon la construction de leur comparatif.","aide":"Adjectif court ou en -y : -er. Adjectif long : more.","type":"categories","categories":[{"id":"c0","texte":"-er than"},{"id":"c1","texte":"more … than"}],"items":[{"id":"i0","texte":"easy"},{"id":"i1","texte":"hot"},{"id":"i2","texte":"comfortable"},{"id":"i3","texte":"expensive"},{"id":"i4","texte":"interesting"},{"id":"i5","texte":"tall"}]},{"enonce":"Associe chaque adjectif à son comparatif.","aide":"Consonne doublée, y devient i, et un irrégulier.","type":"association","gauche":[{"id":"g0","texte":"big"},{"id":"g1","texte":"happy"},{"id":"g2","texte":"bad"},{"id":"g3","texte":"thin"}],"droite":[{"id":"d0","texte":"happier"},{"id":"d1","texte":"worse"},{"id":"d2","texte":"thinner"},{"id":"d3","texte":"bigger"}]}]}$ex$::jsonb,
