","texte":"the tallest boy of the class"},{"id":"g1","texte":"She is best"},{"id":"g2","texte":"the more beautiful city"},{"id":"g3","texte":"the best film I never saw"}],"droite":[{"id":"d0","texte":"She is the best"},{"id":"d1","texte":"the most beautiful city"},{"id":"d2","texte":"the tallest boy in the class"},{"id":"d3","texte":"the best film I have ever seen"}]}]}$ex$::jsonb,
