],"items":[{"id":"i0","texte":"He is getting used to his new school."},{"id":"i1","texte":"You will soon get used to it."},{"id":"i2","texte":"I am used to the noise."},{"id":"i3","texte":"She is used to getting up early."},{"id":"i4","texte":"There used to be a cinema here."},{"id":"i5","texte":"We used to live in Lyon."}]}]}$ex$::jsonb,
