   $ex${"titre":"La sortie au musée des sciences","competence":"analyser-document","situation":"Un professeur écrit aux parents pour la sortie. Plus tard, Zoe explique à son père pourquoi elle a pris son vélo.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"A letter to parents","blocs":["Dear parents,","On Thursday, pupils will visit the science museum. They will bring a packed lunch so that nobody has to buy food. They will leave at 8 a.m. to avoid the traffic. Each pupil must wear a badge so as not to get lost.","Mr Lewis"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Papa et Zoe","participants":[{"nom":"Papa","emoji":"👧","cote":"gauche"},{"nom":"Zoe","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"What did you borrow my bike for?"},{"qui":"Zoe","texte":"To get to the station. I left early so as not to miss the train."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la construction qui exprime un **but négatif**.","aide":"Elle compte quatre mots et se termine par *to*.","type":"zone","document":"mail","multiple":true},{"enonce":"Complète la phrase du courrier.","aide":"*Nobody* est singulier.","type":"trous","segments":["They will bring a packed lunch so that nobody ",0," to buy food."],"banque":["having","had","have","has"]},{"enonce":"Touche les mots qui forment la **question sur le but** du père (*What … for?*).","aide":"Un mot interrogatif au début, une préposition à la fin.","type":"zone","document":"sms","multiple":true},{"enonce":"Dans « To get to the station », quelle construction exprime le but ?","aide":"Qui emprunte le vélo ? Qui va à la gare ?","type":"choix","options":[{"id":"a","texte":"for + nom, pour aller chercher"},{"id":"b","texte":"to + base verbale, avec le même sujet"},{"id":"c","texte":"for + verbe conjugué, à la place"},{"id":"d","texte":"so that + proposition, avec un autre sujet"}],"multiple":false},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Même sujet, autre sujet, but négatif, usage d’un objet.","type":"association","gauche":[{"id":"g0","texte":"J’ai appelé pour poser une question"},{"id":"g1","texte":"Elle chuchote pour que le bébé ne se réveille pas"},{"id":"g2","texte":"Je le note pour ne pas oublier"},{"id":"g3","texte":"Ce couteau sert à couper le pain"}],"droite":[{"id":"d0","texte":"I write it down so as not to forget"},{"id":"d1","texte":"This knife is for cutting bread"},{"id":"d2","texte":"I called to ask a question"},{"id":"d3","texte":"She whispers so that the baby won’t wake up"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m40","m41","m42","m43"]},"explication":"**so as not to** + base verbale : le but négatif, avec *not* avant *to*."},{"cle":{"type":"trous","trous":[["has"]]},"affichage":"has","explication":"**has** : *nobody* se construit avec la 3e personne du singulier."},{"cle":{"type":"zone","ids":["m0","m6"]},"explication":"**What … for?** demande « dans quel but ? »"},{"cle":{"type":"choix","ids":["b"]},"explication":"**to + base verbale** : Zoe emprunte le vélo et Zoe va à la gare, le sujet est le même."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Même sujet : *to*. Autre sujet : *so that*. But négatif : *so as not to*. Usage d’un objet : *for* + -ING."}]$ex$::jsonb),
