   $ex${"titre":"Lena a emménagé à Bath","competence":"analyser-document","situation":"Lena écrit à Marc. Son courriel contient deux erreurs de temps. Plus tard, Marc l’interroge par SMS.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Un courriel de Lena","blocs":["Hi Marc,","I live in Bath for two years now. My sister works in a bakery since June. I met her boss three days ago, and he was very kind.","Lena"],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Marc et Lena","participants":[{"nom":"Marc","emoji":"👧","cote":"gauche"},{"nom":"Lena","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marc","texte":"How long have you lived in Bath?"},{"qui":"Lena","texte":"For two years. I moved here when I was fourteen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** qui devraient être au present perfect.","aide":"Ces situations ont commencé dans le passé et durent encore.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige la première phrase.","aide":"Present perfect : auxiliaire + participe passé.","type":"trous","segments":["I ",0," ",1," in Bath for two years."],"banque":["am","since","live","been","lived","have"]},{"enonce":"Complète la phrase corrigée sur la sœur.","aide":"Juin est un point de départ.","type":"trous","segments":["My sister has worked in a bakery ",0," June."],"banque":["during","for","since","ago"]},{"enonce":"Lena a maintenant seize ans. Quelle phrase dit la même chose que « For two years » avec *since* ?","aide":"Elle a emménagé à quatorze ans, il y a deux ans.","type":"choix","options":[{"id":"a","texte":"She has lived in Bath for she was fourteen."},{"id":"b","texte":"She lived in Bath since she was fourteen."},{"id":"c","texte":"She has lived in Bath since she was fourteen."},{"id":"d","texte":"She has lived in Bath since two years."}],"multiple":false},{"enonce":"Associe chaque erreur à sa correction.","aide":"