  ('c1557564-7e17-53d2-a2db-a5b58af7e4c0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le mot du professeur","competence":"manier-langue","situation":"Mr Hall laisse un mot à sa classe. Le lendemain, Ana raconte ce qu’il a dit.","documents":[{"id":"mot","type":"texte","genre":"lettre","titre":"A note from Mr Hall","blocs":["Dear class,","Don’t forget your books. Come at eight tomorrow. Where do you want to go on Friday?","Mr Hall"],"source":"Mot écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui indique un ordre **négatif**.","aide":"Un ordre négatif commence par *don’t*.","type":"zone","document":"mot","multiple":false},{"enonce":"Rapporte le premier ordre.","aide":"*Not* se place avant *to*.","type":"trous","segments":["Mr Hall told us ",0," forget our books."],"banque":["don’t","not to","not","to not"]},{"enonce":"Rapporte la question du mot : « Il nous a demandé où nous voulions aller. » Commence par He.","aide":"Une question rapportée garde l’ordre de l’affirmative.","type":"ordre","items":[{"id":"a","texte":"asked"},{"id":"b","texte":"to go"},{"id":"c","texte":"He"},{"id":"d","texte":"where"},{"id":"e","texte":"us"},{"id":"f","texte":"wanted"},{"id":"g","texte":"we"}]},{"enonce":"Associe chaque repère direct à son équivalent au discours indirect.","aide":"Les repères de temps et de lieu s’éloignent.","type":"association","gauche":[{"id":"g0","texte":"tomorrow"},{"id":"g1","texte":"yesterday"},{"id":"g2","texte":"now"},{"id":"g3","texte":"here"}],"droite":[{"id":"d0","texte":"there"},{"id":"d1","texte":"the next day"},{"id":"d2","texte":"then"},{"id":"d3","texte":"the day before"}]}]}$ex$::jsonb,
