   $ex${"titre":"Sofia, Max et le projet","competence":"analyser-document","situation":"Sofia et Max échangent des messages. Le lendemain, Max les raconte à sa mère, mais son récit contient des erreurs.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Sofia et Max","participants":[{"nom":"Sofia","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sofia","texte":"I will finish my project tomorrow."},{"qui":"Max","texte":"Are you ready for the test?"},{"qui":"Sofia","texte":"Yes, I can help you here."}],"source":"Messages écrits pour l’exercice"},{"id":"recit","type":"texte","genre":"lettre","titre":"Max parle à sa mère","blocs":["Sofia told me that she will finish her project tomorrow. She said she can help me there."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** que Max n’a pas adaptés au discours indirect.","aide":"Un modal et un repère de temps changent après un verbe introducteur au passé.","type":"zone","document":"recit","multiple":true},{"enonce":"Corrige le début du récit.","aide":"Recul du futur et nouveau repère de temps.","type":"trous","segments":["Sofia told me that she ",0," finish her project ",1,"."],"banque":["the next day","will","would","then","the day before","tomorrow"]},{"enonce":"Sofia rapporte la question de Max à sa mère : « Max m’a demandé si j’étais prête pour le contrôle. » Commence par Max.","aide":"Question fermée : *if*, puis l’ordre de l’affirmative.","type":"ordre","items":[{"id":"a","texte":"ready for the test"},{"id":"b","texte":"I"},{"id":"c","texte":"asked"},{"id":"d","texte":"was"},{"id":"e","texte":"Max"},{"id":"f","texte":"me"},{"id":"g","texte":"if"}]},{"enonce":"Sofia dit : « I can help you here. » Quelle phrase la rapporte correctement ?","aide":"Le modal recule, *here* devient *there*.","type":"choix","options":[{"id":"a","texte":"Sofia said that she can help me here."},{"id":"b","texte":"Sofia said me that she could help you there."},{"id":"c","texte":"Sofia said that she would can help me there."},{"id":"d","texte":"Sofia said that she could help me there."}],"multiple":false},{"enonce":"Associe chaque erreur à sa correction.","aide":"Pense à *say / tell*, à l’ordre des mots et à la place de *not*.","type":"association","gauche":[{"id":"g0","texte":"He said me that…"},{"id":"g1","texte":"She asked where did I live"},{"id":"g2","texte":"He told me to not shout"},{"id":"g3","texte":"She asked me if was I ready"}],"droite":[{"id":"d0","texte":"She asked me if I was ready"},{"id":"d1","texte":"He told me not to shout"},{"id":"d2","texte":"He told me that…"},{"id":"d3","texte":"She asked where I lived"}]}]}$ex$::jsonb,
